/**
 * ============================================================================
 * DYNAMIC NAVIGATION SYSTEM - EASY MAINTENANCE & SWITCHING
 * ============================================================================
 *
 * 🚀 SUPER EASY TO MAINTAIN:
 * - Single toggle flag to switch between static/dynamic navigation
 * - All sidebar components automatically use the same system
 * - No need to update individual components when adding new items
 * - Centralized icon mapping and configuration
 *
 * 🔄 EASY SWITCHING:
 * - Development: Set USE_DYNAMIC_NAVIGATION = false (uses static navigation)
 * - Production: Set USE_DYNAMIC_NAVIGATION = true (uses backend navigation)
 * - Automatic fallback when backend is unavailable
 *
 * 📁 CLEAN ARCHITECTURE:
 * - useDynamicNavigation() hook handles all the logic
 * - Components just call the hook and render
 * - Route protection automatically enabled in dynamic mode
 * - Translation support built-in
 *
 * ============================================================================
 */

/**
 * 🎛️ NAVIGATION MODE SWITCH
 *
 * Change this ONE flag to switch between static and dynamic navigation:
 * - false = Static navigation (hardcoded, no backend calls, no route protection)
 * - true = Dynamic navigation (from backend, with route protection)
 */
export const USE_DYNAMIC_NAVIGATION = true;

// STATIC NAVIGATION - Used when USE_DYNAMIC_NAVIGATION is false
export const navigation: NavigationItem[] = [
  // {
  //   name: "nav.demo",
  //   icon: Users,
  //   children: [
  //     {
  //       name: "nav.products",
  //       href: "/demo/products",
  //       icon: ShieldCheck,
  //     },
  //     {
  //       name: "nav.tree",
  //       href: "/demo/tree",
  //       icon: Users,
  //     },
  //     {
  //       name: "nav.richTextEditor",
  //       href: "/demo/rich-text-editor",
  //       icon: Type,
  //     },
  //   ],
  // },
];

// 🔄 Fallback navigation - used when backend is unavailable (same as static navigation)
export const fallbackNavigation: NavigationItem[] = navigation;

/**
 * ============================================================================
 * 📖 QUICK USAGE GUIDE
 * ============================================================================
 *
 * 🔧 FOR DEVELOPERS:
 * 1. Set USE_DYNAMIC_NAVIGATION = false for development
 * 2. Edit the 'navigation' array below to add/remove items
 * 3. All sidebar components will automatically update
 *
 * 🚀 FOR PRODUCTION:
 * 1. Set USE_DYNAMIC_NAVIGATION = true
 * 2. Implement /MenuItems API endpoint
 * 3. System handles everything automatically
 *
 * 🎨 ADDING NEW STATIC ITEMS:
 * 1. Import icon from lucide-react
 * 2. Add to iconMap if using dynamic navigation
 * 3. Add item to navigation array
 *
 * Example:
 * {
 *   name: "nav.newSection",
 *   href: "/new-section",
 *   icon: NewIcon,
 *   children: [...] // Optional nested items
 * }
 *
 * ============================================================================
 */

/**
 * 🔧 UTILITY FUNCTIONS
 * These are used internally by the navigation system
 */

/**
 * Translates navigation items using the i18n system
 */
export const getNavigationItems = (
  t: (key: string, params?: Record<string, string>) => string,
  navigationItems: NavigationItem[] = fallbackNavigation
): NavigationItem[] => {
  const translateItem = (item: NavigationItem): NavigationItem => ({
    ...item,
    name: item.name.startsWith("nav.") ? t(item.name) : item.name,
    children: item.children?.map(translateItem),
  });

  return navigationItems.map(translateItem);
};

/**
 * Checks if a navigation item or its children match the current pathname.
 *
 * Uses EXACT match for leaf items — no URL prefix matching.
 * Parent items are active if any child in the menu tree matches.
 *
 * When `allItems` is provided (the full navigation tree), the function
 * also falls back to URL prefix matching when NO exact match exists
 * in the entire tree. This handles detail/child pages like /tenants/{id}
 * without false positives between siblings.
 *
 * @param item      The navigation item to check
 * @param pathname  The current URL pathname
 * @param allItems  Optional: full navigation tree (enables prefix fallback)
 */
export const isNavigationItemActive = (
  item: NavigationItem,
  pathname: string,
  allItems?: NavigationItem[]
): boolean => {
  // Exact match for leaf items
  if (item.href && pathname === item.href) return true;

  // Recurse through menu tree children (exact match)
  if (item.children) {
    if (item.children.some((child) => isNavigationItemActive(child, pathname))) {
      return true;
    }
  }

  // ── Prefix fallback for detail/child pages ──
  // Only when full tree context is provided AND no exact match anywhere
  if (allItems) {
    const {
      isMatchWithFallback,
      hasActiveChildWithFallback,
    } = require("@core/ui/layout/shared/nav-utils");
    if (item.href && isMatchWithFallback(item.href, pathname, allItems)) return true;
    if (item.children) {
      return item.children.some(
        (child: NavigationItem) =>
          (child.href && isMatchWithFallback(child.href, pathname, allItems)) ||
          hasActiveChildWithFallback(child, pathname, allItems)
      );
    }
  }

  return false;
};

/**
 * Flattens nested navigation items into a single array (useful for search)
 */
export const getFlatNavigationItems = (
  items: NavigationItem[] = fallbackNavigation
): NavigationItem[] => {
  const flatItems: NavigationItem[] = [];

  const flatten = (items: NavigationItem[]) => {
    items.forEach((item) => {
      if (item.href) {
        flatItems.push(item);
      }
      if (item.children) {
        flatten(item.children);
      }
    });
  };

  flatten(items);
  return flatItems;
};

/**
 * 🔄 Converts backend menu items to frontend navigation format
 * Used internally by the dynamic navigation system
 */
/** Shape of a single backend menu item (bilingual) */
interface BackendMenuItem {
  nameEn?: string;
  nameAr?: string;
  slug?: string;
  /** @deprecated Legacy field — use nameEn/nameAr */
  name?: string;
  /** @deprecated Legacy field — use nameEn/nameAr */
  displayName?: string;
  href?: string;
  icon?: string;
  order?: number;
  resource?: string;
  children?: BackendMenuItem[];
}

/**
 * Gets the current language from localStorage (fallback: 'en')
 */
function getCurrentLanguage(): string {
  if (typeof window === "undefined") return "en";
  try {
    return localStorage.getItem("language") || "en";
  } catch {
    return "en";
  }
}

/**
 * Converts backend menu items to frontend navigation format.
 * Handles bilingual fields (nameEn/nameAr) — picks name by current language.
 * Used internally by the dynamic navigation system.
 */
export const convertMenuItemsToNavigation = (menuItemsData: unknown): NavigationItem[] => {
  // Handle different possible data structures
  let menuItems: BackendMenuItem[] = [];

  if (Array.isArray(menuItemsData)) {
    menuItems = menuItemsData as BackendMenuItem[];
  } else if (menuItemsData && typeof menuItemsData === "object" && "menuItem" in menuItemsData) {
    menuItems = (menuItemsData as Record<string, unknown>).menuItem as BackendMenuItem[];
  } else if (
    menuItemsData &&
    typeof menuItemsData === "object" &&
    Object.keys(menuItemsData as object).length > 0
  ) {
    menuItems = [menuItemsData as BackendMenuItem];
  } else {
    menuItems = [];
  }

  const lang = getCurrentLanguage();

  const convertMenuItem = (item: BackendMenuItem): NavigationItem => {
    // Bilingual name resolution: prefer nameEn/nameAr, fallback to legacy fields
    const displayName =
      lang === "ar"
        ? item.nameAr || item.nameEn || item.name || item.displayName || "Unnamed"
        : item.nameEn || item.name || item.displayName || "Unnamed";

    return {
      name: displayName,
      href: item.href || undefined,
      icon: iconMap[item.icon ?? ""] || iconMap["Package"],
      children: item.children?.map(convertMenuItem) || [],
      disabled: false,
    };
  };

  // Backend already returns only active, non-deleted items
  // Just sort by order and convert
  const sortedMenuItems = [...menuItems].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

  return sortedMenuItems.map(convertMenuItem);
};

"use client";

import * as React from "react";
import { ChevronDown, X } from "lucide-react";
import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";
import { fieldVariants, resolveFieldStyle } from "@core/ui/input";
import { PopoverTrigger, Popover, PopoverContent } from "@core/ui/popover";
import { Badge } from "@core/ui/badge";
import type { GenericSelectOption } from "../generic-select";

export interface SelectTriggerProps {
  id?: string;
  name?: string;
  open: boolean;
  multi: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  required?: boolean;
  describedBy?: string;
  /** Accessible name for this element — see `GenericSelectProps["aria-label"]`'s doc comment. */
  ariaLabel?: string;
  /** Accessible name via reference — see `GenericSelectProps["aria-labelledby"]`'s doc comment. */
  ariaLabelledBy?: string;
  placeholder: string;
  selectedOptions: GenericSelectOption[];
  /** Full label for the single-selected option, including any tree path. */
  displayLabel: string;
  maxSelectedDisplay: number;
  allowClear: boolean;
  onClear: () => void;
  onRemoveOne: (option: GenericSelectOption) => void;
  className?: string;
  /**
   * Anything else the caller put on GenericSelect — data-*, testids and the
   * like. Passed as one object rather than an index signature, which would
   * widen every declared prop above to `unknown`.
   */
  wrapperProps?: React.HTMLAttributes<HTMLDivElement>;
}

/**
 * The field half of the select.
 *
 * It wears the SAME surface as Input and Textarea — `fieldVariants` from
 * input.tsx — so the workspace `inputStyle` setting applies to it. Previously
 * GenericSelect hand-rolled its own trigger chrome, so switching the workspace
 * to `underlined` turned every Input into a bottom rule while every
 * GenericSelect stayed a box, on the same form.
 *
 * THE WHOLE FIELD is the combobox, not a button nested inside it. That matters
 * for three reasons, each of which was a real defect when the button was inner:
 *   1. Radix anchors the panel to the trigger, so a narrow inner button made
 *      the panel detach from the field — and in a multi-select full of chips it
 *      shrank toward zero width and floated mid-field, on opposite sides in the
 *      two writing directions.
 *   2. Clicking the chevron, the padding, or the whitespace between chips did
 *      nothing, because only the inner button opened the panel.
 *   3. The accessible name of a `<button>` is its text content — and a
 *      multi-select's content lived in the sibling chips, so a populated
 *      multi-select announced itself with no name at all. Moving to a
 *      `<div role="combobox">` did NOT fix this by itself: per ARIA,
 *      role="combobox" is Name From: author, not Name From: contents, so a
 *      nameless `<button>` just became a nameless `<div>`. What actually
 *      closes it is the `ariaLabel`/`ariaLabelledBy` props below, applied
 *      to this same element as real `aria-label`/`aria-labelledby`
 *      attributes (Wave 2 Step 2.2's Task 7b a11y fix) -- see those props'
 *      own doc comments and `GenericSelectProps["aria-label"]`'s for the
 *      full mechanism.
 *
 * It is a `div`, not a `button`, because the chips carry their own remove
 * controls and a button may not contain a button.
 *
 * WHICH IS WHY THE `onKeyDown` BELOW IS LOAD-BEARING, not a nicety. Radix's
 * `PopoverTrigger` wires exactly one interaction — `onClick:
 * composeEventHandlers(props.onClick, context.onOpenToggle)` (verified against
 * @radix-ui/react-popover's dist: there is no `onKeyDown` anywhere in that
 * component). Radix gets Enter/Space for free ONLY because it renders
 * `Primitive.button` by default: the browser synthesises a click from those two
 * keys for a real `<button>`. `asChild` over a `<div>` throws that away, and
 * nothing else in this file supplied it — so before this handler existed a
 * keyboard-only user could not open a Select, MultiSelect, tree select or
 * timezone picker ANYWHERE in the product. Every value in the select family was
 * pointer-only.
 *
 * The durable fix would be to render a real `<button type="button">` and let
 * the platform do it. That form is NOT available here: the three nested
 * controls below — each chip's remove button, the "+N" overflow button (itself
 * a `PopoverTrigger` for a second Popover) and the clear button — are
 * interactive content, which a `<button>` may not contain. Nesting them would
 * be invalid HTML with real consequences (browsers do not reliably hit-test a
 * button inside a button, and the inner controls would inherit the outer
 * button's implicit submit/activation behaviour), and it is the reason this
 * element is a `div` in the first place. So the keys are re-implemented instead.
 */
export const SelectTrigger = React.forwardRef<HTMLDivElement, SelectTriggerProps>(
  (
    {
      id,
      name,
      open,
      multi,
      disabled,
      readOnly,
      invalid,
      required,
      describedBy,
      ariaLabel,
      ariaLabelledBy,
      placeholder,
      selectedOptions,
      displayLabel,
      maxSelectedDisplay,
      allowClear,
      onClear,
      onRemoveOne,
      className,
      wrapperProps,
    },
    ref
  ) => {
    const { t } = useI18n();
    const settings = useSettings();
    const [overflowOpen, setOverflowOpen] = React.useState(false);

    const visibleChips = multi ? selectedOptions.slice(0, maxSelectedDisplay) : [];
    const overflowChips = multi ? selectedOptions.slice(maxSelectedDisplay) : [];
    const hasSelection = selectedOptions.length > 0;
    const interactive = !disabled && !readOnly;

    const removeButtonClasses =
      // 24px hit area on a 12px glyph; the negative margins buy it without
      // widening the chip.
      "-my-1 -me-1 inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-nx-ink-3 transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover hover:text-nx-ink focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none";

    return (
      <PopoverTrigger asChild disabled={!interactive}>
        <div
          ref={ref}
          id={id}
          data-name={name}
          role="combobox"
          // Radix supplies aria-expanded and aria-controls (pointing at the
          // panel it actually renders). Only the popup TYPE is overridden —
          // Radix says "dialog", and this one is a listbox.
          aria-haspopup="listbox"
          aria-invalid={invalid || undefined}
          aria-required={required || undefined}
          aria-describedby={describedBy}
          aria-disabled={disabled || undefined}
          aria-readonly={readOnly || undefined}
          // role="combobox" is Name From: author, not Name From: contents --
          // the visible chips/placeholder text below are NOT enough on their
          // own to give this element an accessible name (a prior version of
          // this comment claimed otherwise; verified wrong against real
          // testing-library/AT behavior during Wave 2 Step 2.2's Task 4/7b
          // a11y fix). `aria-labelledby` wins over `aria-label` per the
          // standard accessible-name computation order when a caller
          // supplies both.
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          tabIndex={interactive ? 0 : -1}
          className={cn(
            fieldVariants({ inputStyle: resolveFieldStyle(settings.inputStyle) }),
            "flex min-h-10 w-full flex-wrap items-center gap-1 px-3 py-1.5 text-sm",
            interactive ? "cursor-pointer" : "cursor-default",
            // while its list is up the field stays the active thing
            open && "border-nx-accent shadow-nx-focus",
            // READ_ONLY_FIELD is written with `read-only:enabled:` selectors,
            // which only ever match a form-associated element — on a div the
            // whole string is inert, so the treatment is spelled out here.
            readOnly && "bg-transparent hover:border-nx-line",
            disabled && "border-nx-line bg-nx-raised text-nx-ink-3 shadow-none",
            className
          )}
          {...wrapperProps}
          // Blocks the POINTER path when the field is disabled or read-only.
          //
          // `<PopoverTrigger asChild disabled={!interactive}>` above looks like
          // it already does this, and does not. `disabled` on PopoverTrigger is
          // the NATIVE attribute, meaningful only while Radix renders its
          // default `Primitive.button`; over this `div` it lands as a
          // non-standard DOM attribute the browser ignores, and Radix wires no
          // disabled check of its own into `onOpenToggle`. This is the exact
          // root cause the doc comment above describes for Enter/Space -- and
          // the keyboard half was guarded (`if (!interactive) return`) while the
          // pointer half was not, so a disabled or read-only select opened on
          // click.
          //
          // Nothing shipped was visibly broken, because GenericSelect masks it
          // in its own `handleOpenChange` (`if (disabled || readOnly) return`).
          // That mask is the problem: it makes correctness a thing each
          // consumer must remember, and SelectTrigger is imported directly
          // outside GenericSelect now. Fixed here so the primitive is right and
          // a consumer's own guard is redundant belt-and-braces rather than the
          // only thing standing between a read-only field and an open picker.
          //
          // preventDefault is what suppresses the open, not a return: Radix's
          // trigger is `onClick: composeEventHandlers(props.onClick,
          // context.onOpenToggle)`, and composeEventHandlers skips its second
          // handler once the event is defaultPrevented. Slot runs this child
          // handler before the trigger's own, so the veto lands in time.
          //
          // Placed AFTER {...wrapperProps} and calling the consumer's handler
          // explicitly -- identical discipline to the onKeyDown below, for the
          // same reason: a caller passing onClick for its own purposes must not
          // be able to silently delete this guard. The consumer handler still
          // runs first even when inert, exactly as the keyboard path already
          // does, so the two paths stay symmetric.
          onClick={(event) => {
            wrapperProps?.onClick?.(event);
            if (!interactive) event.preventDefault();
          }}
          // Enter / Space / ArrowDown open the panel — see the "load-bearing"
          // paragraph in this component's doc comment for why the platform does
          // not supply them here.
          //
          // It dispatches a real click rather than calling an open callback so
          // that the ONE toggle path stays Radix's own composed `onClick`: the
          // Popover context's `onOpenToggle`, plus any consumer `onClick`
          // arriving through `wrapperProps`. A parallel "open" channel would
          // drift from the pointer path the first time either side changed.
          //
          // Deliberately placed AFTER {...wrapperProps} — same discipline as
          // dialog.tsx's `onFocusOutside`. A consumer handler still runs (it is
          // composed first, and can veto by calling preventDefault), but a
          // caller who happens to pass `onKeyDown` for its own reasons cannot
          // silently delete the only way to open this control by keyboard.
          //
          // The `event.target !== event.currentTarget` guard keeps the handler
          // off the nested chip-remove / "+N" / clear buttons. Those already
          // stop keydown propagation individually, but this makes the trigger
          // itself the only source, so a future nested control cannot start
          // toggling the panel when someone activates it.
          onKeyDown={(event) => {
            wrapperProps?.onKeyDown?.(event);
            if (!interactive) return;
            if (event.target !== event.currentTarget) return;
            if (event.defaultPrevented) return;
            if (event.altKey || event.ctrlKey || event.metaKey) return;

            const key = event.key;
            if (key !== "Enter" && key !== " " && key !== "ArrowDown") return;
            // ArrowDown is "open", not "toggle" — once the panel is up, cmdk
            // owns the arrows for moving through the options.
            if (key === "ArrowDown" && open) return;

            // Space would scroll the page and Enter would submit a surrounding
            // form; both belong to the combobox while it has focus.
            event.preventDefault();
            event.currentTarget.click();
          }}
        >
          {visibleChips.map((option) => (
            <Badge
              key={option.uniqueKey ?? option.value}
              variant="secondary"
              className="max-w-[12rem] gap-1 pe-1 ps-2"
            >
              <span className="truncate" title={option.label}>
                {option.label}
              </span>
              {interactive && (
                <button
                  type="button"
                  aria-label={t("select.chip.remove", { label: option.label })}
                  className={removeButtonClasses}
                  onClick={(event) => {
                    // Removing a chip must not also toggle the panel.
                    event.stopPropagation();
                    onRemoveOne(option);
                  }}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <X className="h-3 w-3" aria-hidden="true" />
                </button>
              )}
            </Badge>
          ))}

          {overflowChips.length > 0 && (
            // "+N" opens the rest, each still individually removable. The old
            // build replaced ALL chips with a plain "N Selected" span past the
            // third selection, which silently removed the only way to deselect
            // one item without clearing everything.
            <Popover open={overflowOpen} onOpenChange={setOverflowOpen}>
              <PopoverTrigger asChild>
                <button
                  type="button"
                  className="rounded-nx-sm focus-visible:shadow-nx-focus focus-visible:outline-none"
                  aria-label={t("components.multiSelect.moreSelected", {
                    count: overflowChips.length,
                  })}
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <Badge variant="secondary">+{overflowChips.length}</Badge>
                </button>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-56 space-y-1 p-2">
                {overflowChips.map((option) => (
                  <div
                    key={option.uniqueKey ?? option.value}
                    className="flex items-center justify-between gap-2 rounded-nx-sm px-2 py-1 text-sm"
                  >
                    <span className="truncate" title={option.label}>
                      {option.label}
                    </span>
                    {interactive && (
                      <button
                        type="button"
                        aria-label={t("select.chip.remove", { label: option.label })}
                        className={removeButtonClasses}
                        onClick={() => onRemoveOne(option)}
                      >
                        <X className="h-3 w-3" aria-hidden="true" />
                      </button>
                    )}
                  </div>
                ))}
              </PopoverContent>
            </Popover>
          )}

          {/* Single-select shows its value here; multi-select shows the
              placeholder only while nothing is chosen, because the chips above
              already carry the value. */}
          {(!multi || !hasSelection) && (
            <span
              className={cn(
                "flex min-w-0 flex-1 items-center gap-2 truncate",
                hasSelection && !multi && displayLabel ? "text-nx-ink" : "text-nx-ink-3"
              )}
              title={!multi && hasSelection && displayLabel ? displayLabel : undefined}
            >
              {!multi && hasSelection && displayLabel && selectedOptions[0]?.icon && (
                <span className="shrink-0">{selectedOptions[0].icon}</span>
              )}
              <span className="min-w-0 truncate">
                {multi ? placeholder : displayLabel || placeholder}
              </span>
            </span>
          )}

          <div className="ms-auto flex shrink-0 items-center gap-1">
            {allowClear && interactive && hasSelection && (
              <button
                type="button"
                aria-label={t("common.clearSelection")}
                onClick={(event) => {
                  event.stopPropagation();
                  onClear();
                }}
                onKeyDown={(event) => event.stopPropagation()}
                className={cn(removeButtonClasses, "h-5 w-5")}
              >
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            )}
            {!readOnly && (
              <ChevronDown
                aria-hidden="true"
                className={cn(
                  "h-4 w-4 shrink-0 text-nx-ink-3 transition-transform duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                  open && "rotate-180"
                )}
              />
            )}
          </div>
        </div>
      </PopoverTrigger>
    );
  }
);

SelectTrigger.displayName = "SelectTrigger";

/**
 * Dropdown Manager Hook
 *
 * Generic hook for managing dropdown state in view models.
 * Handles preloading, searching, and maintaining current selection.
 * Used by view models that need dropdown functionality.
 */

import { useState, useEffect, useCallback, useMemo } from "react";

export interface DropdownOption {
  value: string;
  label: string;
}

export interface UseDropdownManagerOptions<TItem> {
  /**
   * Service method to fetch items for dropdown
   */
  fetchItems: (params: {
    page?: number;
    pageSize?: number;
    PageSearch?: string;
  }) => Promise<{ data: TItem[] }>;

  /**
   * Function to get the ID from an item
   */
  getId: (item: TItem) => string;

  /**
   * Function to get the label from an item
   */
  getLabel: (item: TItem) => string;

  /**
   * ID of the currently selected item (for edit mode)
   */
  selectedId?: string | null;

  /**
   * Method to fetch a single item by ID (for loading current selection)
   */
  fetchItemById?: (id: string) => Promise<TItem>;

  /**
   * Initial page size for loading items
   */
  initialPageSize?: number;
}

/**
 * Hook to manage dropdown state and operations
 */
export function useDropdownManager<TItem>({
  fetchItems,
  getId,
  getLabel,
  selectedId,
  fetchItemById,
  initialPageSize = 50,
}: UseDropdownManagerOptions<TItem>) {
  const [preloadedOptions, setPreloadedOptions] = useState<DropdownOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentOption, setCurrentOption] = useState<DropdownOption | null>(null);

  // Load initial options
  useEffect(() => {
    const loadInitial = async () => {
      try {
        const response = await fetchItems({
          page: 1,
          pageSize: initialPageSize,
        });
        const options = response.data.map((item) => ({
          value: getId(item),
          label: getLabel(item),
        }));
        queueMicrotask(() => {
          setPreloadedOptions(options);
        });
      } catch (_error) {
        // Silently fail - user will see error when trying to use dropdown
      } finally {
        queueMicrotask(() => {
          setLoading(false);
        });
      }
    };

    loadInitial();
  }, [fetchItems, getId, getLabel, initialPageSize]);

  // Update current option when selectedId changes (for edit mode)
  useEffect(() => {
    if (!selectedId) {
      queueMicrotask(() => {
        setCurrentOption(null);
      });
      return;
    }

    // First check if it's in preloaded options
    const existingOption = preloadedOptions.find((opt) => opt.value === selectedId);
    if (existingOption) {
      queueMicrotask(() => {
        setCurrentOption(existingOption);
      });
      return;
    }

    // If not in preloaded and we have fetchItemById, fetch it
    if (fetchItemById) {
      fetchItemById(selectedId)
        .then((item) => {
          const option = {
            value: getId(item),
            label: getLabel(item),
          };
          queueMicrotask(() => {
            setCurrentOption(option);
            // Add to preloaded options if not already there
            setPreloadedOptions((prev) => {
              if (!prev.find((opt) => opt.value === option.value)) {
                return [...prev, option];
              }
              return prev;
            });
          });
        })
        .catch(() => {
          queueMicrotask(() => {
            setCurrentOption(null);
          });
        });
    } else {
      queueMicrotask(() => {
        setCurrentOption(null);
      });
    }
  }, [selectedId, preloadedOptions, fetchItemById, getId, getLabel]);

  // Server-side search function
  const search = useCallback(
    async (searchTerm: string): Promise<DropdownOption[]> => {
      try {
        const response = await fetchItems({
          page: 1,
          pageSize: initialPageSize,
          PageSearch: searchTerm,
        });
        const options = response.data.map((item) => ({
          value: getId(item),
          label: getLabel(item),
        }));

        // If current option exists and not in results, add it
        if (currentOption && !options.find((opt) => opt.value === currentOption.value)) {
          options.unshift(currentOption);
        }

        return options;
      } catch (_error) {
        return [];
      }
    },
    [fetchItems, getId, getLabel, initialPageSize, currentOption]
  );

  // Get edit options (includes current option if not in preloaded)
  const editOptions = useMemo(() => {
    const options = [...preloadedOptions];
    if (currentOption && !options.find((opt) => opt.value === currentOption.value)) {
      options.unshift(currentOption);
    }
    return options;
  }, [preloadedOptions, currentOption]);

  return {
    preloadedOptions,
    editOptions,
    loading,
    currentOption,
    search,
  };
}

/**
 * Generic Tree View Model Hook
 *
 * A comprehensive, reusable hook for managing hierarchical tree data with:
 * - **TanStack Query integration** for caching and deduplication
 * - Type-safe CRUD operations
 * - Tree traversal and selection
 * - Auto-parent selection
 * - Form handling for create/edit
 *
 * @version 2.0.0 - TanStack Query Integration
 */
"use client";

import { useCallback, useMemo, useState, useRef, useEffect } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import type { PaginationInfo } from "@core/common/pagination";
import { useEnhancedDelete } from "@core/hooks/use-enhanced-delete";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";

export interface TreeNode {
  id: string;
  children?: TreeNode[];
}

export interface TreeService<T extends TreeNode, TCreate, TUpdate> {
  getWithChildren: (params: { page: number; pageSize: number; PageSearch: string }) => Promise<{
    data: T[];
    pagination: PaginationInfo;
  }>;
  create: (data: TCreate) => Promise<T>;
  update: (id: string, data: TUpdate) => Promise<T>;
  delete: (id: string) => Promise<void>;
}

// Create a generic mock service for selectable mode
export function createMockTreeService<T extends TreeNode>(
  mockData: T[],
  searchFields: (keyof T)[] = []
): TreeService<T, unknown, unknown> {
  return {
    getWithChildren: async (params) => {
      // Apply search filter if provided
      let filteredData = mockData;
      if (params.PageSearch && searchFields.length > 0) {
        const searchTerm = params.PageSearch.toLowerCase();
        filteredData = mockData.filter((item: unknown) =>
          searchFields.some((field) => item[field]?.toString().toLowerCase().includes(searchTerm))
        );
      }

      // Apply pagination
      const startIndex = (params.page - 1) * params.pageSize;
      const endIndex = startIndex + params.pageSize;
      const paginatedData = filteredData.slice(startIndex, endIndex);

      return {
        data: paginatedData,
        pagination: {
          itemsCount: filteredData.length,
          pageSize: params.pageSize,
          page: params.page,
          pagesCount: Math.ceil(filteredData.length / params.pageSize),
        },
      };
    },
    create: async () => {
      throw new Error("Not implemented for mock service");
    },
    update: async () => {
      throw new Error("Not implemented for mock service");
    },
    delete: async () => {
      throw new Error("Not implemented for mock service");
    },
  };
}

export interface TreeViewModelConfig<T extends TreeNode> {
  /** TanStack Query key for caching and invalidation */
  queryKey?: string[];
  // Core configuration - make everything optional for maximum flexibility
  itemTypeName?: string;
  itemTypeNamePlural?: string;
  getItemDisplayName?: (item: T) => string;
  getFormFieldName?: (item: T) => string;
  createFormData?: (values: unknown) => unknown;
  updateFormData?: (values: unknown, item: T) => unknown;
  getInitialFormValues?: (item?: T, parent?: T) => unknown;

  // Selectable mode configuration
  selectable?: boolean;
  disabled?: boolean; // Disable selection interactions while maintaining visual state
  getValueToSend?: (item: T) => string;
  initialSelectedValues?: string[];
  onSelectionChange?: (selectedValues: string[]) => void;
  autoSelectParents?: boolean; // Auto-select parent nodes when child is selected

  // Control behavior
  autoLoad?: boolean; // Whether to automatically load data on mount
  staticData?: T[]; // Provide static data instead of using service
  disableOperations?: boolean; // Disable CRUD operations for read-only mode
  /** Stale time in milliseconds (default: 30 seconds) */
  staleTime?: number;
}

export function useTreeViewModel<T extends TreeNode, TCreate = unknown, TUpdate = unknown>(
  service?: TreeService<T, TCreate, TUpdate> | null,
  config: TreeViewModelConfig<T> = {}
) {
  const queryClient = useQueryClient();

  const [pagination, setPagination] = useState<PaginationInfo>({
    itemsCount: 0,
    pageSize: 5,
    page: 1,
    pagesCount: 1,
  });

  // Selectable mode state
  const [selectedValues, setSelectedValues] = useState<string[]>(
    config.initialSelectedValues || []
  );

  const [prevInitialSelected, setPrevInitialSelected] = useState(config.initialSelectedValues);
  if (config.initialSelectedValues !== prevInitialSelected) {
    setPrevInitialSelected(config.initialSelectedValues);
    if (config.initialSelectedValues) {
      setSelectedValues(config.initialSelectedValues);
    }
  }

  // Modal state
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<T | null>(null);
  const [parentForNew, setParentForNew] = useState<T | null>(null);
  const [formValues, setFormValues] = useState<unknown>(config.getInitialFormValues?.() || {});

  // Search state - separate display value from search term
  const [searchValue, setSearchValue] = useState<string>(""); // What user types (immediate)
  const [searchTerm, setSearchTerm] = useState<string>(""); // What triggers API (debounced)
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const { toast } = useEnhancedToast();
  const { t } = useI18n();
  const deleteHook = useEnhancedDelete();

  // Build query key
  const effectiveQueryKey = config.queryKey ?? ["tree"];

  // Build query params
  const page = pagination.page;
  const pageSize = pagination.pageSize;
  const queryParams = useMemo(
    () => ({
      page,
      pageSize,
      PageSearch: searchTerm,
    }),
    [page, pageSize, searchTerm]
  );

  // ==========================================
  // TanStack Query - Main Data Fetching
  // ==========================================
  const {
    data: queryData,
    isLoading,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: [...effectiveQueryKey, queryParams],
    queryFn: () => service?.getWithChildren(queryParams),
    enabled: !!service && !config.staticData && config.autoLoad !== false,
    placeholderData: keepPreviousData,
    staleTime: config.staleTime ?? 30 * 1000,
  });

  // Derive tree data from query or static data
  const queryDataItems = queryData?.data;
  const staticData = config.staticData;
  const tree = useMemo(() => {
    if (staticData) {
      return staticData;
    }
    return queryDataItems ?? [];
  }, [staticData, queryDataItems]);

  // Update pagination from query response
  const [prevPagination, setPrevPagination] = useState(queryData?.pagination);
  if (queryData?.pagination !== prevPagination) {
    setPrevPagination(queryData?.pagination);
    if (queryData?.pagination) {
      const qp = queryData.pagination;
      setPagination((prev) => {
        if (prev.itemsCount === qp.itemsCount && prev.pagesCount === qp.pagesCount) {
          return prev;
        }
        return {
          ...qp,
          pageSize: prev.pageSize,
          pagesCount: qp.pagesCount || 1,
          page: qp.page || 1,
        };
      });
    }
  }

  // ==========================================
  // TanStack Mutations
  // ==========================================
  const createMutation = useMutation({
    mutationFn: (data: TCreate) => {
      if (!service) throw new Error("Service not available");
      return service.create(data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.created").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.createError").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: TUpdate }) => {
      if (!service) throw new Error("Service not available");
      return service.update(id, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.updated").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.updateError").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => {
      if (!service) throw new Error("Service not available");
      return service.delete(id);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.deleted"),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.deleteError"),
        variant: "destructive",
      });
    },
  });

  // ==========================================
  // Tree Helpers
  // ==========================================

  // Helper function to find all parent IDs for a given item
  const findAllParents = useCallback((itemId: string, treeData: T[]): string[] => {
    const parents: string[] = [];

    const findParent = (nodes: T[], targetId: string, currentParents: string[] = []): boolean => {
      for (const node of nodes) {
        if (node.id === targetId) {
          parents.push(...currentParents);
          return true;
        }
        if (node.children && node.children.length > 0) {
          if (findParent(node.children as T[], targetId, [...currentParents, node.id])) {
            return true;
          }
        }
      }
      return false;
    };

    findParent(treeData, itemId);
    return parents;
  }, []);

  // Helper function to find the immediate parent of a given item
  const findImmediateParent = useCallback((itemId: string, treeData: T[]): T | null => {
    const findParent = (nodes: T[], targetId: string): T | null => {
      for (const node of nodes) {
        if (node.children && node.children.length > 0) {
          const hasTargetChild = (node.children as T[]).some((child) => child.id === targetId);
          if (hasTargetChild) {
            return node;
          }
          const found = findParent(node.children as T[], targetId);
          if (found) {
            return found;
          }
        }
      }
      return null;
    };

    return findParent(treeData, itemId);
  }, []);

  // ==========================================
  // Selection handlers
  // ==========================================
  const handleSelectionChange = useCallback(
    (newSelectedValues: string[]) => {
      if (config.disabled) {
        return;
      }

      const finalSelectedValues = [...newSelectedValues];

      // Auto-select parents if enabled
      if (config.autoSelectParents) {
        const allParentsToAdd = new Set<string>();

        newSelectedValues.forEach((selectedId) => {
          const parents = findAllParents(selectedId, tree);
          parents.forEach((parentId) => allParentsToAdd.add(parentId));
        });

        allParentsToAdd.forEach((parentId) => {
          if (!finalSelectedValues.includes(parentId)) {
            finalSelectedValues.push(parentId);
          }
        });
      }

      setSelectedValues(finalSelectedValues);
      if (config.onSelectionChange) {
        config.onSelectionChange(finalSelectedValues);
      }
    },
    [config, tree, findAllParents]
  );

  const clearSelection = useCallback(() => {
    setSelectedValues([]);
    if (config.onSelectionChange) {
      config.onSelectionChange([]);
    }
  }, [config]);

  const selectAll = useCallback(() => {
    const allValues: string[] = [];
    const walk = (nodes: T[]) => {
      nodes.forEach((node) => {
        if (config.getValueToSend) {
          allValues.push(config.getValueToSend(node));
        } else {
          allValues.push(node.id);
        }
        if (node.children && node.children.length > 0) {
          walk(node.children as T[]);
        }
      });
    };
    walk(tree);

    setSelectedValues(allValues);
    if (config.onSelectionChange) {
      config.onSelectionChange(allValues);
    }
  }, [tree, config]);

  // ==========================================
  // CRUD Operations (using mutations)
  // ==========================================
  const disableOperations = config.disableOperations;

  const createItem = useCallback(
    async (data: TCreate) => {
      if (disableOperations) {
        throw new Error("Create operation not available");
      }
      return createMutation.mutateAsync(data);
    },
    [disableOperations, createMutation]
  );

  const updateItem = useCallback(
    async (id: string, data: TUpdate) => {
      if (disableOperations) {
        throw new Error("Update operation not available");
      }
      return updateMutation.mutateAsync({ id, data });
    },
    [disableOperations, updateMutation]
  );

  const deleteItem = useCallback(
    async (item: T) => {
      if (config.disableOperations) {
        throw new Error("Delete operation not available");
      }

      await deleteHook.confirmDelete(
        async () => {
          await deleteMutation.mutateAsync(item.id);
        },
        {
          itemType: t(`${config.itemTypeNamePlural || "items"}`),
          itemName: config.getItemDisplayName?.(item) || "Item",
        }
      );
    },
    [config, deleteHook, t, deleteMutation]
  );

  // ==========================================
  // Pagination handlers
  // ==========================================
  const changePage = useCallback((page: number) => {
    setPagination((prev) => ({ ...prev, page }));
  }, []);

  const changePageSize = useCallback((size: number) => {
    setPagination((prev) => ({ ...prev, pageSize: size, page: 1 }));
  }, []);

  // ==========================================
  // Search handling
  // ==========================================
  const handleSearchChange = useCallback((value: string) => {
    setSearchValue(value);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      if (searchInputRef.current && document.activeElement !== searchInputRef.current) {
        searchInputRef.current.focus();
      }

      setPagination((prev) => ({ ...prev, page: 1 }));
      setSearchTerm(value);
    }, 300);
  }, []);

  const searchItems = useCallback(
    (term: string) => {
      handleSearchChange(term);
    },
    [handleSearchChange]
  );

  // Cleanup
  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, []);

  // ==========================================
  // Form handling
  // ==========================================
  const resetForm = useCallback(() => {
    setEditing(null);
    setParentForNew(null);
    setFormValues(config.getInitialFormValues?.() || {});
  }, [config]);

  const openAddChild = useCallback(
    (parent: T | null) => {
      // Only block if trying to add a child under a parent when tree is empty
      // Allow adding root items (parent === null) even when tree is empty
      if (parent !== null && (!tree || tree.length === 0)) {
        return;
      }

      setEditing(null);
      setParentForNew(parent);
      const initialValues = config.getInitialFormValues?.(undefined, parent || undefined) || {};
      setFormValues(initialValues);
      setModalOpen(true);
    },
    [config, tree]
  );

  const openEdit = useCallback(
    (item: T) => {
      if (!tree || tree.length === 0) {
        return;
      }

      setEditing(item);
      const parent = findImmediateParent(item.id, tree);
      setParentForNew(parent);
      const initialValues = config.getInitialFormValues?.(item, parent || undefined) || {};
      setFormValues(initialValues);
      setModalOpen(true);
    },
    [config, findImmediateParent, tree]
  );

  const onSubmit = useCallback(
    async (data?: unknown) => {
      if (config.disableOperations) {
        return;
      }
      // Use passed data or fallback to state (though GenericForm always passes data)
      const dataToSubmit = data || formValues;

      try {
        if (editing) {
          const updateData = config.updateFormData?.(dataToSubmit, editing) || dataToSubmit;
          await updateItem(editing.id, updateData);
        } else {
          const createData = config.createFormData?.(dataToSubmit) || dataToSubmit;
          await createItem(createData);
        }

        setModalOpen(false);
        resetForm();
      } catch (_error) {
        // Error handling is already done in mutations
      }
    },
    [editing, formValues, createItem, updateItem, config, resetForm]
  );

  // Parent options for forms (flatten current tree)
  const parentOptions = useMemo(() => {
    const result: { id: string; name: string }[] = [];
    const walk = (nodes: T[]) => {
      nodes.forEach((n) => {
        result.push({ id: n.id, name: config.getItemDisplayName?.(n) || n.id });
        if (n.children && n.children.length) walk(n.children as T[]);
      });
    };
    walk(tree);
    return result;
  }, [tree, config]);

  return {
    // Tree data
    tree,
    loading: isLoading,
    isFetching,
    pagination,
    searchValue,
    searchTerm,
    searchInputRef,

    // Tree operations
    listTree: refetch,
    createItem,
    updateItem,
    deleteItem,
    changePage,
    changePageSize,
    handleSearchChange,
    searchItems,

    // Modal and form
    modalOpen,
    setModalOpen,
    editing,
    parentForNew,
    formValues,
    setFormValues,
    parentOptions,
    resetForm,
    openAddChild,
    openEdit,
    onSubmit,

    // Enhanced delete properties
    isDeleting: deleteHook.isDeleting || deleteMutation.isPending,
    showConfirmation: deleteHook.showConfirmation,
    deleteOptions: deleteHook.deleteOptions,
    executeDelete: deleteHook.executeDelete,
    cancelDelete: deleteHook.cancelDelete,

    // Mutation states
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,

    // Selectable mode properties
    selectedValues,
    handleSelectionChange,
    clearSelection,
    selectAll,
    disabled: config.disabled,

    // Config
    config,
  };
}

export type TreeViewModel<T extends TreeNode, TCreate, TUpdate> = ReturnType<
  typeof useTreeViewModel<T, TCreate, TUpdate>
>;

import React from "react";
import { render, screen, waitFor, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import { Dialog, DialogContent, DialogTitle } from "../dialog";

/**
 * Dialog outside-click allowlist tests.
 *
 * DialogContent's onInteractOutside/onPointerDownOutside handlers call
 * e.preventDefault() when the outside-click target is inside one of six
 * allowlisted portal selectors (dropdown/select/date-picker/popper/listbox/
 * option), so pointer-downs inside those live portals never dismiss the
 * dialog. Any other outside click falls through to Radix's default dismiss
 * behavior and closes it.
 */

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({
    t: (key: string) => key,
    direction: "ltr",
  }),
}));

function renderDialog(onOpenChange: (open: boolean) => void) {
  return render(
    <div>
      {/* Sits outside the Dialog's portal tree — a plain non-allowlisted node. */}
      <button type="button">outside-plain</button>
      {/* Simulates a live portal (e.g. a Select's popper content) rendered
          outside the DialogContent DOM subtree but allowlisted by selector. */}
      <div data-radix-popper-content-wrapper="">
        <div role="listbox">
          <div role="option">option-1</div>
        </div>
      </div>
      <Dialog open onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogTitle>Test dialog</DialogTitle>
          <button type="button">inside</button>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Radix's DismissableLayer registers its `pointerdown` listener on
// `document` inside a `setTimeout(0)` (so the open-triggering pointerdown
// itself is never seen), and — for a non-"touch" pointerType — dispatches
// onPointerDownOutside synchronously from that same listener. So a real
// test has to: wait a tick for the listener to attach, then fire a
// `pointerdown` (not click) whose `pointerType` is anything but "touch".
function pointerDownOutside(target: Element) {
  fireEvent.pointerDown(target, { pointerId: 1, button: 0, pointerType: "mouse" });
}

describe("Dialog outside-click allowlist", () => {
  it("does not close when the outside click lands inside an allowlisted portal selector", async () => {
    const onOpenChange = vi.fn();
    // Radix marks every sibling of the modal `aria-hidden="true"` while open
    // (its aria-hide side effect), so the allowlisted portal content below
    // is invisible to `getByRole`/`getByText` even though it's live DOM —
    // query it directly off `baseElement` instead.
    const { baseElement } = renderDialog(onOpenChange);

    expect(screen.getByText("Test dialog")).toBeInTheDocument();

    // Let DismissableLayer's effect (setTimeout(0)) attach its listener.
    await new Promise((resolve) => setTimeout(resolve, 0));

    const option = baseElement.querySelector("[role='option']");
    expect(option).not.toBeNull();
    pointerDownOutside(option as Element);

    await waitFor(() => {
      expect(onOpenChange).not.toHaveBeenCalledWith(false);
    });
    expect(screen.getByText("Test dialog")).toBeInTheDocument();
  });

  it("closes when the outside click lands on a non-allowlisted element", async () => {
    const onOpenChange = vi.fn();
    const { baseElement } = renderDialog(onOpenChange);

    expect(screen.getByText("Test dialog")).toBeInTheDocument();

    await new Promise((resolve) => setTimeout(resolve, 0));

    const outsideButton = baseElement.querySelector("button");
    expect(outsideButton).not.toBeNull();
    expect(outsideButton?.textContent).toBe("outside-plain");
    pointerDownOutside(outsideButton as Element);

    await waitFor(() => {
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });
  });
});

// GenericForm draws Wave 3.4's three field types through the CustomFields
// extension registry.
//
// THE BLOCKER THIS FILE PINS is the one `"entity-reference"` already taught this
// component once. A custom-field FieldConfig genuinely reaches <GenericForm>:
// generic-crud-view.tsx concatenates `useCustomFieldsFormFields`'s fieldConfigs
// into the `fields` it hands over, and `visibleFields` filters only on
// isVisible/permissions. So a declared-but-undrawn type falls through to the
// switch's default `<Input type={field.type} value={formData[field.name] ?? ""}>`
// -- a text box painting the stored object as `[object Object]`, which the first
// keystroke replaces with a string the server answers with a 422.
//
// AND THE TRAP THIS TIME WAS SHARPER, which is why it is worth naming here: all
// three types had a plausible-looking existing member to reuse. `"file"`,
// `"image"` and `"richtext"` are all real, all rendered, and all produce the
// WRONG VALUE SHAPE -- a browser `File`, a base64 string, and a bare string. So
// reusing any of them would not have fallen through to the default arm at all; it
// would have drawn a working-looking control whose every save is refused. Three
// new members plus three `EXTENSION_DRAWN_FIELD_TYPES` entries is the fix, and
// the tests below assert both halves: the extension is consulted, and this
// component draws nothing itself.
//
// THE EXTENSION IS A FAKE HERE ON PURPOSE. This file's subject is the ROUTING
// contract `core` owns -- that GenericForm hands the registered control its six
// promised props, suppresses its own label, and keeps the raw value. That the
// real controls work is pinned on the module side, by
// GenericFormCustomFieldControl.richTextMedia.test.tsx, which mounts this same
// GenericForm over the real implementations.
import React from "react";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach } from "vitest";
import "@testing-library/jest-dom/vitest";
import { GenericForm, type FieldConfig } from "./generic-form";
import {
  registerCustomFieldsExtension,
  type CustomFieldFormControlProps,
  type CustomFieldsExtensionApi,
} from "@core/crud/customFieldsExtension";

vi.mock("@core/providers/permission-provider", () => ({
  usePermissions: () => ({
    permissions: [],
    hasPermission: () => true,
    hasAnyPermission: () => true,
    hasAllPermissions: () => true,
    canAccessPage: () => true,
    roleNames: [],
    isSuperAdmin: true,
  }),
  PermissionGate: ({ children }: { children: unknown }) => children,
}));

/** Every prop the fake control was handed, newest last -- the routing contract's observation point. */
let receivedProps: CustomFieldFormControlProps[] = [];

/**
 * Stands in for the CustomFields module's real controls. Renders its OWN label
 * (as all three real controls do, which is why the host must suppress its own)
 * and a `role="group"` region wired to the three host-owned a11y props, so the
 * assertions below are about what GenericForm PASSES rather than about what a
 * stub happens to paint. The "set" button emits a shape decided by the caller,
 * so one stub serves all three field types.
 */
function FakeFieldControl({
  field,
  value,
  onChange,
  disabled,
  invalid,
  describedBy,
}: CustomFieldFormControlProps) {
  receivedProps.push({ field, value, onChange, disabled, invalid, describedBy });
  const emitted =
    field.type === "rich-text"
      ? { html: "<p>typed by the control</p>" }
      : { entityTypeKey: "media.file", entityId: "ENC-9" };
  return (
    <div>
      <label htmlFor={field.name}>{field.label}</label>
      <div
        id={field.name}
        role="group"
        aria-label={field.label ?? field.name}
        aria-invalid={invalid || undefined}
        aria-describedby={describedBy}
        aria-disabled={disabled || undefined}
      >
        {value ? "holds a value" : "empty"}
      </div>
      <button type="button" onClick={() => onChange(emitted)}>
        {`set ${field.type}`}
      </button>
    </div>
  );
}

function makeApi(overrides: Partial<CustomFieldsExtensionApi> = {}): CustomFieldsExtensionApi {
  return {
    getFormFields: vi.fn().mockResolvedValue([]),
    saveValues: vi.fn().mockResolvedValue(undefined),
    getBulkColumnValues: vi.fn().mockResolvedValue({ columns: [], valuesByOwnerId: {} }),
    InlineAddTrigger: () => null,
    FieldControl: FakeFieldControl,
    ...overrides,
  };
}

/**
 * The real, namespaced names the extension produces (`encodeCustomFieldName`), so
 * the id/`htmlFor`/`aria-describedby` wiring is exercised on the shape production
 * actually uses.
 */
const MEDIA_FILE: FieldConfig = {
  name: "__cf__waiver",
  label: "Waiver",
  type: "media-file",
  referenceTargetEntityTypeKey: "media.file",
};
const MEDIA_IMAGE: FieldConfig = {
  name: "__cf__photo",
  label: "Photo",
  type: "media-image",
  referenceTargetEntityTypeKey: "media.file",
};
const RICH_TEXT: FieldConfig = {
  name: "__cf__notes",
  label: "Notes",
  type: "rich-text",
  placeholder: "What happened?",
};

const ALL_THREE: readonly (readonly [string, FieldConfig, unknown])[] = [
  ["media-file", MEDIA_FILE, { entityTypeKey: "media.file", entityId: "ENC-1" }],
  ["media-image", MEDIA_IMAGE, { entityTypeKey: "media.file", entityId: "ENC-2" }],
  ["rich-text", RICH_TEXT, { html: "<p>Stored prose</p>" }],
];

beforeEach(() => {
  receivedProps = [];
  // The registry has no unregister; every test re-registers instead. The
  // FieldControl-absent path lives in its own file for exactly that reason.
  registerCustomFieldsExtension(makeApi());
});

describe("GenericForm — Wave 3.4 types route to the extension control", () => {
  it.each(ALL_THREE)("consults the extension for a %s field and draws no input itself", (
    _label,
    field
  ) => {
    // RED WITHOUT THE FIX, both halves: getByRole("group") throws because the
    // extension is never consulted, and queryByRole("textbox") finds the
    // fallthrough `<Input type={field.type}>`.
    const { container } = render(
      <GenericForm fields={[field]} onSubmit={async () => {}} onCancel={() => {}} />
    );

    expect(screen.getByRole("group", { name: field.label })).toBeInTheDocument();
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(container.querySelector(`input[type="${field.type}"]`)).toBeNull();
  });

  it.each(ALL_THREE)(
    "hands the %s control the RAW stored object, with no `?? \"\"` normalisation",
    (_label, field, stored) => {
      // The `?? ""` in the fallthrough is precisely what turned an absent object
      // into an empty string the server then refused. Absent must stay absent and
      // present must stay the object -- both asserted, because a control that
      // received `""` for a stored object would satisfy neither.
      render(
        <GenericForm
          fields={[field]}
          initialValues={{ [field.name]: stored }}
          onSubmit={async () => {}}
          onCancel={() => {}}
        />
      );

      expect(receivedProps.at(-1)?.value).toEqual(stored);
    }
  );

  it.each(ALL_THREE)("leaves an absent %s value undefined, not an empty string", (_label, field) => {
    render(<GenericForm fields={[field]} onSubmit={async () => {}} onCancel={() => {}} />);
    expect(receivedProps.at(-1)?.value).toBeUndefined();
  });

  it.each(ALL_THREE)(
    "leaves nothing typeable that could overwrite a stored %s value",
    async (_label, field, stored) => {
      // The DATA-LOSS shape, reproduced rather than described. RED WITHOUT THE
      // FIX: the fallthrough renders an `<input>` holding "[object Object]", the
      // keystroke below replaces the whole value with a string, and the submitted
      // value is "typed". With the fix there is no input to find, so the keystroke
      // has nowhere to land and the value survives untouched.
      const onSubmit = vi.fn().mockResolvedValue(undefined);
      const { container } = render(
        <GenericForm
          fields={[field]}
          initialValues={{ [field.name]: stored }}
          onSubmit={onSubmit}
          onCancel={() => {}}
        />
      );

      const stray = container.querySelector<HTMLInputElement>(`input#${CSS.escape(field.name)}`);
      if (stray) fireEvent.change(stray, { target: { value: "typed" } });

      fireEvent.click(screen.getByRole("button", { name: "common.save" }));

      await waitFor(() => expect(onSubmit).toHaveBeenCalledTimes(1));
      expect(onSubmit.mock.calls[0][0][field.name]).toEqual(stored);
    }
  );

  it.each(ALL_THREE)(
    "routes the %s control's onChange into form state and submits exactly what it emitted",
    async (_label, field) => {
      // No translation anywhere between the control and `onSubmit` -- which is the
      // point for these two envelopes in particular. `{ html }` and
      // `{ entityTypeKey, entityId }` are spelled identically on the wire in both
      // directions, so a rename in this path would be a data-loss bug rather than
      // a style choice.
      const onSubmit = vi.fn().mockResolvedValue(undefined);
      render(<GenericForm fields={[field]} onSubmit={onSubmit} onCancel={() => {}} />);

      fireEvent.click(screen.getByRole("button", { name: `set ${field.type}` }));
      fireEvent.click(screen.getByRole("button", { name: "common.save" }));

      await waitFor(() => expect(onSubmit).toHaveBeenCalledTimes(1));
      expect(onSubmit.mock.calls[0][0][field.name]).toEqual(
        field.type === "rich-text"
          ? { html: "<p>typed by the control</p>" }
          : { entityTypeKey: "media.file", entityId: "ENC-9" }
      );
    }
  );

  it.each(ALL_THREE)("renders exactly one label for a %s field — the host suppresses its own", (
    _label,
    field
  ) => {
    // RED IN THE OPPOSITE DIRECTION: with the render arm added but the type left
    // out of `EXTENSION_DRAWN_FIELD_TYPES`'s label-suppression condition, two
    // identical `<label for>` nodes render. Counted on the `for` attribute rather
    // than on visible text, so a control that labels itself differently cannot
    // mask a duplicate.
    const { container } = render(
      <GenericForm fields={[field]} onSubmit={async () => {}} onCancel={() => {}} />
    );
    expect(container.querySelectorAll(`label[for="${field.name}"]`)).toHaveLength(1);
  });

  it("carries the reference target pin through to a media control untouched", () => {
    // `FieldConfig.referenceTargetEntityTypeKey` is a CARRIER this component never
    // reads: the whole `field` is handed across, and the pin is read on the module
    // side. Media needs the same carrier the reference types use, so this asserts
    // it survives the crossing rather than being dropped for a type the property's
    // own doc comment was written before.
    render(
      <GenericForm fields={[MEDIA_FILE]} onSubmit={async () => {}} onCancel={() => {}} />
    );
    expect(receivedProps.at(-1)?.field.referenceTargetEntityTypeKey).toBe("media.file");
  });

  it("carries a rich-text field's placeholder through, since the control needs it for the editor", () => {
    render(<GenericForm fields={[RICH_TEXT]} onSubmit={async () => {}} onCancel={() => {}} />);
    expect(receivedProps.at(-1)?.field.placeholder).toBe("What happened?");
  });
});

describe("GenericForm — Wave 3.4 types receive the host-owned a11y facts", () => {
  it.each(ALL_THREE)("passes the form's read-only state to a %s control as disabled", (
    _label,
    field
  ) => {
    render(
      <GenericForm fields={[field]} onSubmit={async () => {}} onCancel={() => {}} readOnly />
    );
    expect(receivedProps.at(-1)?.disabled).toBe(true);
    expect(screen.getByRole("group", { name: field.label })).toHaveAttribute(
      "aria-disabled",
      "true"
    );
  });

  it.each(ALL_THREE)("passes a per-field disabled flag to a %s control", (_label, field) => {
    render(
      <GenericForm
        fields={[{ ...field, disabled: true }]}
        onSubmit={async () => {}}
        onCancel={() => {}}
      />
    );
    expect(receivedProps.at(-1)?.disabled).toBe(true);
  });

  it.each(ALL_THREE)(
    "passes the host's own validation verdict and hint node to a %s control",
    async (_label, field) => {
      // The verdict only exists after a failed submit, so this drives one. The
      // negative half is asserted first, on the initial render, so the positive
      // half cannot pass against a control that is handed `invalid` unconditionally.
      render(
        <GenericForm
          fields={[{ ...field, required: true }]}
          onSubmit={async () => {}}
          onCancel={() => {}}
        />
      );
      expect(receivedProps.at(-1)?.invalid).toBeFalsy();

      fireEvent.click(screen.getByRole("button", { name: "common.save" }));

      await waitFor(() => expect(receivedProps.at(-1)?.invalid).toBe(true));
      // And the description id is a real node holding the message, not a dangling
      // reference -- an id list pointing at nothing announces nothing and looks
      // identical to correct wiring if only the attribute is checked.
      const describedBy = receivedProps.at(-1)?.describedBy;
      expect(describedBy).toBeTruthy();
      expect(document.getElementById(String(describedBy))?.textContent).toContain(
        "validation.required"
      );
    }
  );
});

/**
 * useThemeMarketplace — React hook for theme marketplace state management
 *
 * Handles: listing, featured, detail, apply, favorite, filtering, pagination.
 * All business logic is server-side — this hook is presentation-only.
 *
 * Uses customizationContainer.themeMarketplaceRepository (Clean Architecture).
 * NO direct API calls in this hook.
 *
 * @module customization/presentation
 */
"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { customizationContainer } from "@modules/customization/di";
import type { ThemeCard } from "../../domain/entities/ThemeCard";
import type { ThemeDetail } from "../../domain/entities/ThemeDetail";
import type { ThemeFilterState } from "../../domain/types/ThemeTypes";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";

interface UseThemeMarketplaceReturn {
  // Data
  themes: ThemeCard[];
  featuredThemes: ThemeCard[];
  selectedTheme: ThemeDetail | null;
  totalCount: number;
  page: number;
  pageSize: number;

  // Filter state
  filters: ThemeFilterState;
  setFilters: (filters: Partial<ThemeFilterState>) => void;
  resetFilters: () => void;

  // Pagination
  setPage: (page: number) => void;

  // Loading states
  isLoading: boolean;
  isFeaturedLoading: boolean;
  isDetailLoading: boolean;
  isApplying: boolean;
  isTogglingFavorite: string | null; // slug being toggled

  // Actions
  loadThemes: () => Promise<void>;
  loadFeatured: () => Promise<void>;
  openDetail: (slug: string) => Promise<void>;
  closeDetail: () => void;
  applyTheme: (slug: string, merge?: boolean) => Promise<boolean>;
  toggleFavorite: (slug: string) => Promise<void>;

  // View mode
  viewMode: "grid" | "list";
  setViewMode: (mode: "grid" | "list") => void;

  // Tab
  activeTab: "browse" | "favorites" | "featured";
  setActiveTab: (tab: "browse" | "favorites" | "featured") => void;
}

const DEFAULT_FILTERS: ThemeFilterState = {
  search: "",
  category: "",
  sortBy: "popular",
};

/**
 * React hook/ViewModel orchestrating state and data flows for theme marketplace.
 * Handles active states updates, form fields validations, and browser navigation controllers.
 */
export function useThemeMarketplace(): UseThemeMarketplaceReturn {
  const { themeMarketplaceRepository } = customizationContainer;
  const { toast } = useEnhancedToast();
  const { t } = useI18n();

  // Data
  const [themes, setThemes] = useState<ThemeCard[]>([]);
  const [featuredThemes, setFeaturedThemes] = useState<ThemeCard[]>([]);
  const [selectedTheme, setSelectedTheme] = useState<ThemeDetail | null>(null);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const pageSize = 12;

  // Filter
  const [filters, setFiltersState] = useState<ThemeFilterState>(DEFAULT_FILTERS);

  // Loading
  const [isLoading, setIsLoading] = useState(false);
  const [isFeaturedLoading, setIsFeaturedLoading] = useState(false);
  const [isDetailLoading, setIsDetailLoading] = useState(false);
  const [isApplying, setIsApplying] = useState(false);
  const [isTogglingFavorite, setIsTogglingFavorite] = useState<string | null>(null);

  // UI
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [activeTab, setActiveTab] = useState<"browse" | "favorites" | "featured">("browse");

  // Prevent duplicate calls
  const loadingRef = useRef(false);

  const setFilters = useCallback((updates: Partial<ThemeFilterState>) => {
    setFiltersState((prev) => ({ ...prev, ...updates }));
    setPage(1); // Reset to page 1 on filter change
  }, []);

  const resetFilters = useCallback(() => {
    setFiltersState(DEFAULT_FILTERS);
    setPage(1);
  }, []);

  // ── Load themes (marketplace or favorites) ──
  const loadThemes = useCallback(async () => {
    if (loadingRef.current) return;
    loadingRef.current = true;
    setIsLoading(true);

    try {
      const result =
        activeTab === "favorites"
          ? await themeMarketplaceRepository.getFavorites({ page, pageSize })
          : await themeMarketplaceRepository.getThemes({ page, pageSize, filters });

      setThemes(result.items);
      setTotalCount(result.totalCount);
    } catch (_err) {
      toast({ title: t("studio.gallery.toasts.loadFailed"), variant: "destructive" });
    } finally {
      setIsLoading(false);
      loadingRef.current = false;
    }
  }, [themeMarketplaceRepository, page, pageSize, filters, activeTab, toast, t]);

  // ── Load featured ──
  const loadFeatured = useCallback(async () => {
    setIsFeaturedLoading(true);
    try {
      const result = await themeMarketplaceRepository.getFeatured();
      setFeaturedThemes(result);
    } catch {
      // Silent — featured is non-critical
    } finally {
      setIsFeaturedLoading(false);
    }
  }, [themeMarketplaceRepository]);

  // ── Open detail ──
  const openDetail = useCallback(
    async (slug: string) => {
      setIsDetailLoading(true);
      try {
        const detail = await themeMarketplaceRepository.getBySlug(slug);
        setSelectedTheme(detail);
      } catch {
        toast({ title: t("studio.gallery.toasts.detailLoadFailed"), variant: "destructive" });
      } finally {
        setIsDetailLoading(false);
      }
    },
    [themeMarketplaceRepository, toast, t]
  );

  const closeDetail = useCallback(() => {
    setSelectedTheme(null);
  }, []);

  // ── Apply theme ──
  const applyTheme = useCallback(
    async (slug: string, merge: boolean = false): Promise<boolean> => {
      setIsApplying(true);
      try {
        await themeMarketplaceRepository.apply(slug, merge);
        toast({
          title: t("studio.gallery.toasts.applySuccessTitle"),
          description: t("studio.gallery.toasts.applySuccessDescription"),
        });

        // Refresh themes to update isApplied state
        await loadThemes();
        return true;
      } catch (err: unknown) {
        const message =
          err?.message || err?.response?.data?.error || t("studio.gallery.toasts.applyFailedFallback");
        // Detect system admin without tenant context
        if (
          message.includes("System admins") ||
          message.includes("target tenant") ||
          message.includes("drilldown")
        ) {
          toast({
            title: t("studio.gallery.toasts.noTenantSelectedTitle"),
            description: t("studio.gallery.toasts.noTenantSelectedDescription"),
            variant: "destructive",
          });
        } else {
          toast({ title: message, variant: "destructive" });
        }
        return false;
      } finally {
        setIsApplying(false);
      }
    },
    [themeMarketplaceRepository, toast, loadThemes, t]
  );

  // ── Toggle favorite ──
  const toggleFavorite = useCallback(
    async (slug: string) => {
      setIsTogglingFavorite(slug);
      try {
        await themeMarketplaceRepository.toggleFavorite(slug);

        // Optimistic update: toggle isFavorited and likeCount in local state
        setThemes((prev) =>
          prev.map((t) =>
            t.slug === slug
              ? t.copyWith({
                  isFavorited: !t.isFavorited,
                  likeCount: t.isFavorited ? t.likeCount - 1 : t.likeCount + 1,
                })
              : t
          )
        );
        setFeaturedThemes((prev) =>
          prev.map((t) =>
            t.slug === slug
              ? t.copyWith({
                  isFavorited: !t.isFavorited,
                  likeCount: t.isFavorited ? t.likeCount - 1 : t.likeCount + 1,
                })
              : t
          )
        );
        if (selectedTheme?.slug === slug) {
          // Detail is a ThemeDetail (extends ThemeCard), reload from server for clean state
          await openDetail(slug);
        }
      } catch {
        toast({ title: t("studio.gallery.toasts.favoriteUpdateFailed"), variant: "destructive" });
      } finally {
        setIsTogglingFavorite(null);
      }
    },
    [themeMarketplaceRepository, selectedTheme, toast, openDetail, t]
  );

  // ── Auto-load on filter/page/tab change ──
  useEffect(() => {
    queueMicrotask(() => {
      void loadThemes();
    });
  }, [loadThemes]);

  // ── Load featured on mount ──
  useEffect(() => {
    queueMicrotask(() => {
      void loadFeatured();
    });
  }, [loadFeatured]);

  return {
    themes,
    featuredThemes,
    selectedTheme,
    totalCount,
    page,
    pageSize,
    filters,
    setFilters,
    resetFilters,
    setPage,
    isLoading,
    isFeaturedLoading,
    isDetailLoading,
    isApplying,
    isTogglingFavorite,
    loadThemes,
    loadFeatured,
    openDetail,
    closeDetail,
    applyTheme,
    toggleFavorite,
    viewMode,
    setViewMode,
    activeTab,
    setActiveTab,
  };
}

// FILE-EXCEPTION: file length
/**
 * Role Detail ViewModel
 *
 * Handles all business logic for the Role Detail page.
 * SOLID: All state, queries, mutations, and handlers live here.
 * View is pure UI (~60 lines).
 *
 * NOTE: Permission grouping is done 100% by the backend.
 * The frontend receives PermissionModuleGroup[] directly — no reduce/groupBy.
 */
"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { useParams } from "next/navigation";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { appLogger } from "@core/common/logger";
import { useI18n } from "@core/providers/i18n-provider";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { identityContainer } from "@modules/identity/di";
import type {
  Permission,
  PermissionModuleGroup,
  PermissionCategoryGroup,
} from "@modules/identity/permissions";
import type { Role } from "../../domain/entities/Role";
import type { PermissionAssignmentJson } from "../../domain/types/PermissionTypes";

// === Types ===
/**
 * Exported type in the identity/roles module.
 */
export type { PermissionModuleGroup, PermissionCategoryGroup };

/**
 * Interface defining property specifications, keys types, and structural contract rules for role detail header props.
 */
export interface RoleDetailHeaderProps {
  role: Role | undefined;
  isLoading: boolean;
  isSaving: boolean;
  onSave: () => void;
  /** Whether the permission matrix has unsaved edits since the last load/save. */
  isDirty: boolean;
}

/**
 * Interface defining property specifications, keys types, and structural contract rules for role info card props.
 */
export interface RoleInfoCardProps {
  role: Role | undefined;
  isLoading: boolean;
  selectedCount: number;
  totalCount: number;
}

/**
 * Interface defining property specifications, keys types, and structural contract rules for permission tree props.
 */
export interface PermissionTreeProps {
  moduleGroups: PermissionModuleGroup[];
  isLoading: boolean;
  expandedKeys: Set<string>;
  selectedPermissionCodes: Set<string>;
  searchQuery: string;
  onSearchChange: (value: string) => void;
  onToggleExpand: (key: string) => void;
  onToggleAllInCategory: (permissions: Permission[]) => void;
  onTogglePermission: (code: string) => void;
  onExpandAll: () => void;
  onCollapseAll: () => void;
  assignments: Map<string, PermissionAssignmentJson>;
  onUpdateConfig: (code: string, assignment: PermissionAssignmentJson) => void;
  onBulkScopeUpdate: (scope: string) => void;
  bulkScopeValue: string;
  setBulkScopeValue: (scope: string) => void;
}

// === ViewModel ===
/**
 * React hook/ViewModel orchestrating state and data flows for role detail view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useRoleDetailViewModel(roleIdOverride?: string) {
  const { t } = useI18n();
  const params = useParams();
  // The route passes the id explicitly where it can; reading the dynamic
  // segment stays the fallback so a bare `<RoleDetailView/>` under `roles/[id]`
  // keeps working. Both resolve to the same value on that route.
  const roleId = roleIdOverride ?? (params.id as string);
  const queryClient = useQueryClient();
  const { success, error: toastError } = useEnhancedToast();
  const { roleRepository } = identityContainer;

  // === STATE ===
  const [assignments, setAssignments] = useState<Map<string, PermissionAssignmentJson>>(new Map());
  const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState("");
  const [bulkScopeValue, setBulkScopeValue] = useState<string>("");
  // Tracks unsaved edits so the header's Save button and "unsaved changes"
  // banner reflect real state instead of just the in-flight save request —
  // mirrors useOAuthAppDetailViewModel's isDirty flag.
  const [isDirty, setIsDirty] = useState(false);
  // Tracks which role we've already initialized `assignments` for — mirrors
  // useRolePermissionsDialog's initializedRoleId guard. Without it, the
  // staleTime: 0 query below refetches on every refocus/reconnect and hands
  // back a new array reference for the SAME role, which would silently
  // overwrite unknown in-progress unsaved permission edits.
  const [initializedRoleId, setInitializedRoleId] = useState<string | null>(null);

  // === QUERIES ===
  const { data: role, isLoading: roleLoading } = useQuery<Role>({
    queryKey: ["role", roleId],
    queryFn: () => roleRepository.getById(roleId),
    enabled: !!roleId,
    staleTime: 0,
    gcTime: 0,
  });

  const { data: rolePermissions, isLoading: rolePermissionsLoading } = useQuery<unknown[]>({
    queryKey: ["rolePermissions", roleId],
    queryFn: () => roleRepository.getRolePermissions(roleId),
    enabled: !!roleId,
    staleTime: 0,
    gcTime: 0,
  });

  // ── Backend-driven grouped permissions (Module → Category → Permissions) ──
  // ZERO client-side grouping: backend sends the tree, frontend renders it.
  const { data: moduleGroups = [], isLoading: permissionsLoading } = useQuery<
    PermissionModuleGroup[]
  >({
    queryKey: ["myTenantAvailablePermissionsGrouped", searchQuery],
    queryFn: () => roleRepository.getMyTenantAvailablePermissionsGrouped(searchQuery || undefined),
  });

  // ── Auto-expand all modules when data first loads ──
  // This replaces the broken `expandedKeys.size === 0 ? true` fallback.
  // When moduleGroups loads, populate expandedKeys with all module keys
  // so every module starts expanded. Users can then collapse individually.
  const hasInitializedExpand = useRef(false);
  useEffect(() => {
    if (moduleGroups.length > 0 && !hasInitializedExpand.current) {
      hasInitializedExpand.current = true;
      const keys = new Set<string>();
      moduleGroups.forEach((mg) => {
        keys.add(`module:${mg.module}`);
      });
      queueMicrotask(() => {
        setExpandedKeys(keys);
      });
    }
  }, [moduleGroups]);

  // === INITIALIZE ASSIGNMENTS WHEN DATA LOADS (once per role) ===
  // Guarded on roleId, not on rolePermissions' array reference: staleTime: 0
  // means a window refocus can refetch and hand back a new (content-identical
  // or server-normalized) array for the SAME role at unknown time, including
  // mid-edit. Only a genuine role switch — or the first load — should reset
  // the editor; a background refetch of the role you're already editing must
  // not. The post-save refetch doesn't need to re-sync either: local
  // `assignments` already holds exactly what was just saved, and
  // saveMutation's onSuccess already clears isDirty directly.
  useEffect(() => {
    if (!roleId || rolePermissionsLoading || initializedRoleId === roleId) return;
    if (!rolePermissions || rolePermissions.length === 0) return;

    appLogger.debug("rolePermissions raw:", rolePermissions);

    const newAssignments = new Map<string, PermissionAssignmentJson>();

    rolePermissions.forEach((rp: unknown) => {
      const code = rp.permissionCode || rp.PermissionCode || rp.code || rp.Code;

      if (code) {
        newAssignments.set(code, {
          permissionId: rp.permissionId || rp.PermissionId || rp.id || rp.Id,
          scopeOverride: rp.scope || rp.ScopeOverride,
          restrictedFields: Array.isArray(rp.restrictedFields) ? rp.restrictedFields : undefined,
        });
      }
    });

    appLogger.debug("Initialized assignments map size:", newAssignments.size);
    queueMicrotask(() => {
      setAssignments(newAssignments);
      setIsDirty(false);
      setInitializedRoleId(roleId);
    });
  }, [roleId, rolePermissions, rolePermissionsLoading, initializedRoleId]);

  // Helper: flatten all permissions from module groups (for save payload)
  const getAllPermissionsFlat = (): Permission[] => {
    return moduleGroups.flatMap((mg) => mg.categories.flatMap((cat) => cat.permissions));
  };

  // === MUTATION ===
  const saveMutation = useMutation({
    mutationFn: async () => {
      const allPermissions = getAllPermissionsFlat();
      const codeToIdMap = new Map<string, string>();
      allPermissions.forEach((p) => {
        codeToIdMap.set(p.code, p.id);
      });

      const permissionsPayload = Array.from(assignments.entries())
        .map(([code, assignment]) => {
          let id = assignment.permissionId;
          if (!id) {
            id = codeToIdMap.get(code) || "";
          }
          return {
            permissionId: id,
            scopeOverride: assignment.scopeOverride ?? null,
            restrictedFields: assignment.restrictedFields ?? [],
          };
        })
        .filter((p) => !!p.permissionId);

      appLogger.debug("Saving permissions payload:", permissionsPayload);

      await roleRepository.assignPermissions(roleId, {
        permissions: permissionsPayload,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["rolePermissions", roleId] });
      queryClient.invalidateQueries({ queryKey: ["role", roleId] });
      // Reset immediately rather than waiting on the invalidated refetch, so
      // the Save button/banner clear the instant the save resolves.
      setIsDirty(false);
      success({
        title: t("common.success"),
        description: t("roleDetail.permissionsSaved"),
      });
    },
    onError: (err: Error) => {
      toastError({
        title: t("common.error"),
        description: err.message,
      });
    },
  });

  // === HANDLERS ===
  const toggleExpand = useCallback((key: string) => {
    setExpandedKeys((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  }, []);

  const togglePermission = useCallback(
    (permissionCode: string) => {
      setIsDirty(true);
      setAssignments((prev) => {
        const next = new Map(prev);
        if (next.has(permissionCode)) {
          next.delete(permissionCode);
        } else {
          // Find permission ID from module groups
          const allPerms = moduleGroups.flatMap((mg) =>
            mg.categories.flatMap((cat) => cat.permissions)
          );
          const permission = allPerms.find((p) => p.code === permissionCode);
          next.set(permissionCode, {
            permissionId: permission?.id || "",
            scopeOverride: "Tenant",
            restrictedFields: [],
          });
        }
        return next;
      });
    },
    [moduleGroups]
  );

  const updateAssignment = useCallback((code: string, assignment: PermissionAssignmentJson) => {
    setIsDirty(true);
    setAssignments((prev) => {
      const next = new Map(prev);
      next.set(code, assignment);
      return next;
    });
  }, []);

  const toggleCategoryPermissions = useCallback(
    (permissions: Permission[]) => {
      const categoryCodes = permissions.map((p) => p.code);
      const allSelected = categoryCodes.every((code) => assignments.has(code));

      setIsDirty(true);
      setAssignments((prev) => {
        const next = new Map(prev);
        categoryCodes.forEach((code) => {
          if (allSelected) {
            next.delete(code);
          } else {
            if (!next.has(code)) {
              const permission = permissions.find((p) => p.code === code);
              next.set(code, {
                permissionId: permission?.id || "",
                scopeOverride: "Tenant",
                restrictedFields: [],
              });
            }
          }
        });
        return next;
      });
    },
    [assignments]
  );

  const expandAll = useCallback(() => {
    // Expand both module and category keys
    const keys = new Set<string>();
    moduleGroups.forEach((mg) => {
      keys.add(`module:${mg.module}`);
      mg.categories.forEach((cat) => {
        keys.add(`cat:${mg.module}:${cat.category}`);
      });
    });
    setExpandedKeys(keys);
  }, [moduleGroups]);

  const collapseAll = useCallback(() => {
    setExpandedKeys(new Set());
  }, []);

  const handleSave = useCallback(() => {
    saveMutation.mutate();
  }, [saveMutation]);

  const bulkUpdateScope = useCallback((scope: string) => {
    const scopeValue = scope === "own_tenant" ? undefined : scope;

    setIsDirty(true);
    setAssignments((prev) => {
      const next = new Map(prev);
      Array.from(next.keys()).forEach((key) => {
        const current = next.get(key)!;
        next.set(key, { ...current, scopeOverride: scopeValue });
      });
      return next;
    });
  }, []);

  // === DERIVED STATE ===
  const isLoading = roleLoading || permissionsLoading || rolePermissionsLoading;
  const selectedPermissionCodes = new Set(assignments.keys());
  const totalPermCount = moduleGroups.reduce(
    (sum, mg) => sum + mg.categories.reduce((s, cat) => s + cat.permissions.length, 0),
    0
  );

  // === RETURN PROPS FOR VIEW ===
  return {
    header: {
      role,
      isLoading: roleLoading,
      isSaving: saveMutation.isPending,
      onSave: handleSave,
      isDirty,
    } as RoleDetailHeaderProps,

    info: {
      role,
      isLoading: roleLoading,
      selectedCount: assignments.size,
      totalCount: totalPermCount,
    } as RoleInfoCardProps,

    permissions: {
      moduleGroups,
      isLoading,
      expandedKeys,
      selectedPermissionCodes,
      searchQuery,
      onSearchChange: setSearchQuery,
      onToggleExpand: toggleExpand,
      onToggleAllInCategory: toggleCategoryPermissions,
      onTogglePermission: togglePermission,
      onExpandAll: expandAll,
      onCollapseAll: collapseAll,
      assignments: assignments,
      onUpdateConfig: updateAssignment,
      onBulkScopeUpdate: bulkUpdateScope,
      bulkScopeValue,
      setBulkScopeValue,
    } as PermissionTreeProps,
  };
}

