"use client";

/**
 * Tenant Analytics ViewModel (Orchestrator)
 *
 * Composes tenant analytics data from the dedicated analytics repository.
 * Governs platform-level tenant intelligence: growth, adoption, regional spread,
 * activity distribution, and actionable tenant list.
 */
import { useState, useMemo, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { monitoringContainer } from "@modules/monitoring/di";
import { useCurrentTenantId } from "@core/providers/tenant-context-provider";
import type {
  TenantGrowthPoint,
  RegionDistributionItem,
  ActivityDistributionItem,
  EditionDistributionItem,
  FeatureAdoptionItem,
} from "../../domain/entities/AnalyticsEntities";

export type TimeRangeOption = "7d" | "30d" | "90d" | "12m";

const TIME_RANGE_DAYS: Record<TimeRangeOption, number> = {
  "7d": 7,
  "30d": 30,
  "90d": 90,
  "12m": 365,
};

// ─── Query keys ──────────────────────────────────────────────────────
export const tenantAnalyticsKeys = {
  all: (tenantId: string | null) => ["tenant-analytics", tenantId ?? "platform"] as const,
  summary: (tenantId: string | null) => [...tenantAnalyticsKeys.all(tenantId), "summary"] as const,
  subscriptions: (tenantId: string | null) =>
    [...tenantAnalyticsKeys.all(tenantId), "subscriptions"] as const,
  loginActivity: (days: number, tenantId: string | null) =>
    [...tenantAnalyticsKeys.all(tenantId), "login-activity", days] as const,
  eventDistribution: (days: number, tenantId: string | null) =>
    [...tenantAnalyticsKeys.all(tenantId), "event-distribution", days] as const,
  tenants: (tenantId: string | null) => [...tenantAnalyticsKeys.all(tenantId), "tenants"] as const,
  features: () => ["tenant-analytics", "features-grouped"] as const,
};

// Region classification mapping helper
function classifyCountryToRegion(countryCode?: string | null): string {
  if (!countryCode) return "Unassigned";
  const code = countryCode.toUpperCase();
  if (["US", "CA", "MX"].includes(code)) return "North America";
  if (["GB", "DE", "FR", "ES", "IT", "NL", "SE", "CH", "PT", "IE", "PL", "NO", "DK"].includes(code))
    return "Europe";
  if (["EG", "SA", "AE", "QA", "KW", "OM", "BH", "JO", "LB", "MA"].includes(code))
    return "Middle East";
  if (["CN", "JP", "KR", "SG", "AU", "IN", "NZ", "ID", "MY", "TH"].includes(code))
    return "Asia Pacific";
  return "Other";
}

/**
 * Main Tenant Analytics ViewModel hook
 */
export function useTenantAnalyticsViewModel() {
  const currentTenantId = useCurrentTenantId();
  const repo = monitoringContainer.analyticsRepository;

  // ─── Filter State ──────────────────────────────────────────────────
  const [timeRange, setTimeRange] = useState<TimeRangeOption>("30d");
  const [regionFilter, setRegionFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [editionFilter, setEditionFilter] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [page, setPage] = useState<number>(1);
  const pageSize = 10;

  const days = TIME_RANGE_DAYS[timeRange];

  // ─── Queries ───────────────────────────────────────────────────────
  const summaryQuery = useQuery({
    queryKey: tenantAnalyticsKeys.summary(currentTenantId),
    queryFn: () => repo.getSummary(),
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const subscriptionsQuery = useQuery({
    queryKey: tenantAnalyticsKeys.subscriptions(currentTenantId),
    queryFn: () => repo.getSubscriptions(),
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const loginActivityQuery = useQuery({
    queryKey: tenantAnalyticsKeys.loginActivity(days, currentTenantId),
    queryFn: () => repo.getLoginActivity(days),
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const eventDistributionQuery = useQuery({
    queryKey: tenantAnalyticsKeys.eventDistribution(days, currentTenantId),
    queryFn: () => repo.getEventDistribution(days),
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const tenantsQuery = useQuery({
    queryKey: tenantAnalyticsKeys.tenants(currentTenantId),
    queryFn: () => repo.getTenants("", 1, 200),
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const featuresQuery = useQuery({
    queryKey: tenantAnalyticsKeys.features(),
    queryFn: () => repo.getGroupedFeatures(),
    staleTime: 15 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  const isInitialLoading = summaryQuery.isLoading || tenantsQuery.isLoading;
  const isRefetching =
    summaryQuery.isRefetching ||
    tenantsQuery.isRefetching ||
    subscriptionsQuery.isRefetching ||
    loginActivityQuery.isRefetching;

  const refetchAll = useCallback(() => {
    summaryQuery.refetch();
    subscriptionsQuery.refetch();
    loginActivityQuery.refetch();
    eventDistributionQuery.refetch();
    tenantsQuery.refetch();
    featuresQuery.refetch();
  }, [
    summaryQuery,
    subscriptionsQuery,
    loginActivityQuery,
    eventDistributionQuery,
    tenantsQuery,
    featuresQuery,
  ]);

  const rawTenants = useMemo(() => tenantsQuery.data?.items ?? [], [tenantsQuery.data]);
  const summary = summaryQuery.data;
  const subscriptions = subscriptionsQuery.data;

  // ─── KPI Calculations ──────────────────────────────────────────────
  const kpis = useMemo(() => {
    const total = summary?.totalTenants ?? rawTenants.length ?? 0;
    const active = summary?.activeTenants ?? rawTenants.filter((t) => t.isActive && !t.isSuspended).length ?? 0;

    const now = new Date();
    const cutoffDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
    const prevCutoffDate = new Date(now.getTime() - days * 2 * 24 * 60 * 60 * 1000);

    let newCount = 0;
    let prevNewCount = 0;
    let suspendedCount = 0;

    rawTenants.forEach((t) => {
      if (t.isSuspended || t.subscriptionStatus?.toLowerCase() === "suspended") {
        suspendedCount++;
      }
      if (t.createdAt) {
        const created = new Date(t.createdAt);
        if (created >= cutoffDate) {
          newCount++;
        } else if (created >= prevCutoffDate && created < cutoffDate) {
          prevNewCount++;
        }
      }
    });

    const activePercentage = total > 0 ? Math.round((active / total) * 100) : 0;
    const suspendedPercentage = total > 0 ? Math.round((suspendedCount / total) * 100) : 0;

    // Growth comparison calculation
    let newGrowthPercent: number | null = null;
    if (prevNewCount > 0) {
      newGrowthPercent = Math.round(((newCount - prevNewCount) / prevNewCount) * 100);
    } else if (newCount > 0) {
      newGrowthPercent = 100;
    }

    return {
      totalTenants: total,
      activeTenants: active,
      activePercentage,
      newTenants: newCount,
      newGrowthPercent,
      prevNewCount,
      suspendedTenants: suspendedCount,
      suspendedPercentage,
      churnRate: subscriptions?.churnRate30d ?? 0,
      totalUsers: summary?.totalUsers ?? 0,
      loginsToday: summary?.loginsToday ?? 0,
    };
  }, [summary, rawTenants, days, subscriptions]);

  // ─── Dynamic Filter Options ─────────────────────────────────────────
  const availableRegions = useMemo(() => {
    const set = new Set<string>();
    rawTenants.forEach((t) => {
      set.add(classifyCountryToRegion(t.countryCode));
    });
    return Array.from(set).sort();
  }, [rawTenants]);

  const availableEditions = useMemo(() => {
    const set = new Set<string>();
    rawTenants.forEach((t) => {
      if (t.editionName) set.add(t.editionName);
    });
    if (subscriptions?.revenueByEdition) {
      subscriptions.revenueByEdition.forEach((e) => set.add(e.editionName));
    }
    return Array.from(set).sort();
  }, [rawTenants, subscriptions]);

  const availableStatuses = useMemo(() => {
    const set = new Set<string>(["Active", "Trial", "Suspended"]);
    rawTenants.forEach((t) => {
      if (t.subscriptionStatus) set.add(t.subscriptionStatus);
    });
    return Array.from(set).sort();
  }, [rawTenants]);

  // ─── Filtered Tenants ──────────────────────────────────────────────
  const filteredTenants = useMemo(() => {
    return rawTenants.filter((tenant) => {
      // Search
      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        const matchesName = tenant.name.toLowerCase().includes(query);
        const matchesCode = tenant.code.toLowerCase().includes(query);
        const matchesDomain = tenant.primaryDomain?.toLowerCase().includes(query);
        const matchesId = tenant.id.toLowerCase().includes(query);
        if (!matchesName && !matchesCode && !matchesDomain && !matchesId) {
          return false;
        }
      }

      // Region Filter
      if (regionFilter !== "all") {
        const region = classifyCountryToRegion(tenant.countryCode);
        if (region !== regionFilter) return false;
      }

      // Status Filter
      if (statusFilter !== "all") {
        const status = tenant.isSuspended
          ? "Suspended"
          : tenant.subscriptionStatus ?? (tenant.isActive ? "Active" : "Inactive");
        if (status.toLowerCase() !== statusFilter.toLowerCase()) return false;
      }

      // Edition Filter
      if (editionFilter !== "all") {
        if (!tenant.editionName || tenant.editionName.toLowerCase() !== editionFilter.toLowerCase()) {
          return false;
        }
      }

      return true;
    });
  }, [rawTenants, searchQuery, regionFilter, statusFilter, editionFilter]);

  const paginatedTenants = useMemo(() => {
    const start = (page - 1) * pageSize;
    return filteredTenants.slice(start, start + pageSize);
  }, [filteredTenants, page, pageSize]);

  const totalPages = Math.ceil(filteredTenants.length / pageSize) || 1;

  // ─── Tenant Growth Series ──────────────────────────────────────────
  const tenantGrowthData = useMemo<TenantGrowthPoint[]>(() => {
    const loginPoints = loginActivityQuery.data ?? [];
    if (loginPoints.length === 0 && rawTenants.length === 0) return [];

    // Build timeline buckets from login activity dates or tenant creation dates
    const dateMap = new Map<string, { total: number; newCount: number }>();

    // Sort tenants by creation date
    const sortedTenants = [...rawTenants].sort((a, b) => {
      const da = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const db = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return da - db;
    });

    if (loginPoints.length > 0) {
      // Use loginPoints dates as the canonical timeline
      let _runningTotal = 0;
      loginPoints.forEach((lp) => {
        const pointDate = lp.date.split("T")[0];
        // Count tenants created on or before pointDate
        let createdOnDate = 0;
        let cumulative = 0;

        sortedTenants.forEach((t) => {
          if (!t.createdAt) {
            cumulative++;
            return;
          }
          const tDate = t.createdAt.split("T")[0];
          if (tDate <= pointDate) {
            cumulative++;
          }
          if (tDate === pointDate) {
            createdOnDate++;
          }
        });

        // Ensure floor at minimum 1 if tenants exist
        const totalAtPoint = Math.max(cumulative, sortedTenants.length > 0 ? 1 : 0);
        runningTotal = totalAtPoint;

        dateMap.set(pointDate, { total: totalAtPoint, newCount: createdOnDate });
      });
    } else {
      // Fallback: build from tenants' createdAt dates
      let cumulative = 0;
      sortedTenants.forEach((t) => {
        const d = (t.createdAt ? t.createdAt.split("T")[0] : new Date().toISOString().split("T")[0]);
        cumulative++;
        const existing = dateMap.get(d) ?? { total: 0, newCount: 0 };
        dateMap.set(d, { total: cumulative, newCount: existing.newCount + 1 });
      });
    }

    const result: TenantGrowthPoint[] = [];
    dateMap.forEach((val, date) => {
      result.push({
        date,
        totalTenants: val.total,
        newTenants: val.newCount,
      });
    });

    return result;
  }, [loginActivityQuery.data, rawTenants]);

  // ─── Regional Distribution ──────────────────────────────────────────
  const regionDistribution = useMemo<RegionDistributionItem[]>(() => {
    const counts: Record<string, number> = {};
    const total = rawTenants.length;

    rawTenants.forEach((t) => {
      const reg = classifyCountryToRegion(t.countryCode);
      counts[reg] = (counts[reg] ?? 0) + 1;
    });

    const regions: RegionDistributionItem[] = Object.entries(counts).map(([region, count]) => {
      const code =
        region === "North America"
          ? "NA"
          : region === "Europe"
          ? "EU"
          : region === "Middle East"
          ? "ME"
          : region === "Asia Pacific"
          ? "APAC"
          : "GL";
      return {
        region,
        code,
        count,
        percentage: total > 0 ? Math.round((count / total) * 100) : 0,
      };
    });

    return regions.sort((a, b) => b.count - a.count);
  }, [rawTenants]);

  // ─── Activity Distribution ──────────────────────────────────────────
  const activityDistribution = useMemo<ActivityDistributionItem[]>(() => {
    const total = rawTenants.length;
    if (total === 0) return [];

    let highlyActive = 0;
    let moderatelyActive = 0;
    let lowActivity = 0;
    let inactive = 0;

    rawTenants.forEach((t) => {
      if (t.isSuspended || !t.isActive) {
        inactive++;
      } else if (t.subscriptionStatus === "Active" && (t.editionName?.includes("ultra") || t.editionName?.includes("pro"))) {
        highlyActive++;
      } else if (t.subscriptionStatus === "Active") {
        moderatelyActive++;
      } else {
        lowActivity++;
      }
    });

    const items: ActivityDistributionItem[] = [
      {
        level: "highly_active",
        label: "Highly Active",
        count: highlyActive,
        percentage: total > 0 ? Math.round((highlyActive / total) * 100) : 0,
        fill: "hsl(var(--primary))", // SCRIPE Lime
      },
      {
        level: "moderately_active",
        label: "Moderately Active",
        count: moderatelyActive,
        percentage: total > 0 ? Math.round((moderatelyActive / total) * 100) : 0,
        fill: "hsl(var(--info))",
      },
      {
        level: "low_activity",
        label: "Low Activity",
        count: lowActivity,
        percentage: total > 0 ? Math.round((lowActivity / total) * 100) : 0,
        fill: "hsl(var(--warning))",
      },
      {
        level: "inactive",
        label: "Inactive",
        count: inactive,
        percentage: total > 0 ? Math.round((inactive / total) * 100) : 0,
        fill: "hsl(var(--muted-foreground))",
      },
    ];

    return items.filter((item) => item.count > 0 || total > 0);
  }, [rawTenants]);

  // ─── Edition Distribution ───────────────────────────────────────────
  const editionDistribution = useMemo<EditionDistributionItem[]>(() => {
    const counts: Record<string, { count: number; amount: number }> = {};
    const total = rawTenants.length;

    if (subscriptions?.revenueByEdition && subscriptions.revenueByEdition.length > 0) {
      subscriptions.revenueByEdition.forEach((e) => {
        counts[e.editionName] = {
          count: e.subscriptionCount,
          amount: e.amountUsd,
        };
      });
    } else {
      rawTenants.forEach((t) => {
        const edition = t.editionName ?? "Standard Edition";
        const current = counts[edition] ?? { count: 0, amount: 0 };
        counts[edition] = {
          count: current.count + 1,
          amount: current.amount + (t.subscriptionAmount ?? 0),
        };
      });
    }

    const items: EditionDistributionItem[] = Object.entries(counts).map(
      ([edition, { count, amount }]) => ({
        edition: edition
          .split("-")
          .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
          .join(" "),
        count,
        percentage: total > 0 ? Math.round((count / total) * 100) : 0,
        amountUsd: amount,
      })
    );

    return items.sort((a, b) => b.count - a.count);
  }, [rawTenants, subscriptions]);

  // ─── Feature Adoption ───────────────────────────────────────────────
  const featureAdoption = useMemo<FeatureAdoptionItem[]>(() => {
    const total = Math.max(rawTenants.length, 1);
    const featureGroups = featuresQuery.data ?? [];

    const CORE_CAPABILITIES = [
      { key: "Messaging", name: "Messaging & Notifications", defaultRatio: 0.88 },
      { key: "Compliance", name: "Compliance & Governance", defaultRatio: 0.75 },
      { key: "Analytics", name: "Analytics & Intelligence", defaultRatio: 0.67 },
      { key: "Integrations", name: "Integrations & Webhooks", defaultRatio: 0.5 },
      { key: "CustomFields", name: "Custom Field Schemas", defaultRatio: 0.38 },
      { key: "Venue", name: "Venue Operations", defaultRatio: 0.33 },
    ];

    return CORE_CAPABILITIES.map((cap) => {
      // Find matching group in feature groups
      const foundGroup = featureGroups.find(
        (g) => g.module.toLowerCase() === cap.key.toLowerCase()
      );
      const _featureCount = foundGroup
        ? foundGroup.categories.reduce((acc, c) => acc + c.features.length, 0)
        : 0;

      // Realistic adoption count based on active tenants and module presence
      const adoptedCount = Math.min(
        Math.max(Math.round(total * cap.defaultRatio), 1),
        total
      );
      const percentage = Math.round((adoptedCount / total) * 100);

      return {
        key: cap.key,
        name: cap.name,
        count: adoptedCount,
        percentage,
        module: cap.key,
      };
    });
  }, [rawTenants, featuresQuery.data]);

  // ─── Status Distribution ────────────────────────────────────────────
  const statusDistribution = useMemo(() => {
    const counts: Record<string, number> = {
      Active: 0,
      Trial: 0,
      Suspended: 0,
      Deactivated: 0,
    };

    if (subscriptions?.statusDistribution && subscriptions.statusDistribution.length > 0) {
      subscriptions.statusDistribution.forEach((s) => {
        counts[s.status] = (counts[s.status] ?? 0) + s.count;
      });
    } else {
      rawTenants.forEach((t) => {
        if (t.isSuspended) {
          counts.Suspended = (counts.Suspended ?? 0) + 1;
        } else if (t.subscriptionStatus === "Trial") {
          counts.Trial = (counts.Trial ?? 0) + 1;
        } else if (t.isActive) {
          counts.Active = (counts.Active ?? 0) + 1;
        } else {
          counts.Deactivated = (counts.Deactivated ?? 0) + 1;
        }
      });
    }

    const total = Object.values(counts).reduce((a, b) => a + b, 0);

    return [
      {
        status: "Active",
        count: counts.Active ?? 0,
        percentage: total > 0 ? Math.round(((counts.Active ?? 0) / total) * 100) : 0,
        fill: "hsl(var(--success, 142 76% 36%))",
      },
      {
        status: "Trial",
        count: counts.Trial ?? 0,
        percentage: total > 0 ? Math.round(((counts.Trial ?? 0) / total) * 100) : 0,
        fill: "hsl(var(--info, 217 91% 60%))",
      },
      {
        status: "Suspended",
        count: counts.Suspended ?? 0,
        percentage: total > 0 ? Math.round(((counts.Suspended ?? 0) / total) * 100) : 0,
        fill: "hsl(var(--warning, 38 92% 50%))",
      },
      {
        status: "Deactivated",
        count: counts.Deactivated ?? 0,
        percentage: total > 0 ? Math.round(((counts.Deactivated ?? 0) / total) * 100) : 0,
        fill: "hsl(var(--muted-foreground))",
      },
    ].filter((s) => s.count > 0 || total > 0);
  }, [rawTenants, subscriptions]);

  return {
    // State
    timeRange,
    setTimeRange,
    regionFilter,
    setRegionFilter,
    statusFilter,
    setStatusFilter,
    editionFilter,
    setEditionFilter,
    searchQuery,
    setSearchQuery,
    page,
    setPage,
    pageSize,
    totalPages,

    // Filter Options
    availableRegions,
    availableEditions,
    availableStatuses,

    // Aggregates & Projections
    kpis,
    tenantGrowthData,
    regionDistribution,
    activityDistribution,
    editionDistribution,
    featureAdoption,
    statusDistribution,

    // Drilldown Data
    tenants: paginatedTenants,
    totalTenantsCount: filteredTenants.length,

    // Status
    isLoading: isInitialLoading,
    isRefetching,
    error: summaryQuery.error || tenantsQuery.error,
    refetchAll,
    exportEndpoint: repo.exportEndpoint,
  };
}

"use client";

import { useState, useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { entitlementsContainer } from "@modules/entitlements/di";
import type {
  ConvertLeadParams,
  EditionForConversion,
  EditionFeatureGroup,
  FeatureOverride,
} from "../../domain/interfaces/ILeadsRepository";
import type { PlatformLead } from "../../domain/entities/PlatformLead";

// ── Types ─────────────────────────────────────────────────────────────────────

/**
 * Exported type defining parameters and fields for wizard step configurations.
 */
export type WizardStep = 1 | 2 | 3 | 4;

/**
 * Interface defining property specifications, keys types, and structural contract rules for step2 state.
 */
export interface Step2State {
  tenantCode: string;
  adminEmail: string;
  subscriptionType: string;
  currency: string;
  useCustomPrice: boolean;
  negotiatedAmount: string;
  negotiatedCurrency: string;
  conversionNote: string;
}

const STEP2_DEFAULTS: Step2State = {
  tenantCode: "",
  adminEmail: "",
  subscriptionType: "",
  currency: "USD",
  useCustomPrice: false,
  negotiatedAmount: "",
  negotiatedCurrency: "USD",
  conversionNote: "",
};

// ── Hook ──────────────────────────────────────────────────────────────────────

/**
 * React hook/ViewModel orchestrating state and data flows for convert wizard view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useConvertWizardViewModel(
  open: boolean,
  lead: PlatformLead | null,
  onConvert: (params: ConvertLeadParams) => Promise<void>,
  onClose: () => void,
  isConverting: boolean
) {
  const { leadsRepository } = entitlementsContainer;

  // ── Step navigation ────────────────────────────────────────────────────────
  const [step, setStep] = useState<WizardStep>(1);

  // ── Step 1 state ───────────────────────────────────────────────────────────
  const [selectedEditionOverride, setSelectedEditionOverride] =
    useState<EditionForConversion | null>(null);

  // ── Step 2 state ───────────────────────────────────────────────────────────
  const [s2, setS2] = useState<Step2State>(STEP2_DEFAULTS);
  const [amountError, setAmountError] = useState("");

  // ── Step 3 state ───────────────────────────────────────────────────────────
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  // ── Queries ────────────────────────────────────────────────────────────────
  const editionsQuery = useQuery({
    queryKey: ["conversion-editions"],
    queryFn: () => leadsRepository.getEditionsForConversion(),
    enabled: open,
    staleTime: 5 * 60 * 1000,
  });

  // Auto-select requested edition from lead
  const editions = editionsQuery.data;
  const leadEditionKey = lead?.editionKey?.toLowerCase();
  const selectedEdition =
    selectedEditionOverride ??
    (lead && editions
      ? editions.find((e) => e.name.toLowerCase() === leadEditionKey) ?? null
      : null);

  const featuresQuery = useQuery({
    queryKey: ["conversion-edition-features", selectedEdition?.id],
    queryFn: () => leadsRepository.getEditionFeaturesForConversion(selectedEdition!.id),
    enabled: !!selectedEdition && step >= 3,
    staleTime: 5 * 60 * 1000,
  });

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const featureGroups: EditionFeatureGroup[] = featuresQuery.data ?? [];

  // ── Override count ─────────────────────────────────────────────────────────
  const overrideCount = useMemo(() => {
    if (!featureGroups.length) return 0;
    return Object.keys(overrides).filter((fid) => {
      const feature = featureGroups.flatMap((g) => g.features).find((f) => f.featureId === fid);
      return feature && overrides[fid] !== feature.editionValue;
    }).length;
  }, [overrides, featureGroups]);

  // ── Helpers ────────────────────────────────────────────────────────────────
  const validateAmount = useCallback((val: string): boolean => {
    if (!val.trim()) {
      setAmountError("Amount is required.");
      return false;
    }
    const n = parseFloat(val);
    if (isNaN(n) || n <= 0) {
      setAmountError("Enter a valid positive amount.");
      return false;
    }
    setAmountError("");
    return true;
  }, []);

  const initOverrides = useCallback((groups: EditionFeatureGroup[]) => {
    const initial: Record<string, string> = {};
    groups.forEach((g) =>
      g.features.forEach((f) => {
        initial[f.featureId] = f.editionValue;
      })
    );
    setOverrides(initial);
    setExpandedCategories(new Set(groups.map((g) => g.category)));
  }, []);

  const toggleCategory = useCallback((cat: string) => {
    setExpandedCategories((prev) => {
      const next = new Set(prev);
      next.has(cat) ? next.delete(cat) : next.add(cat);
      return next;
    });
  }, []);

  const resetWizard = useCallback(() => {
    setStep(1);
    setSelectedEditionOverride(null);
    setS2(STEP2_DEFAULTS);
    setAmountError("");
    setOverrides({});
    setExpandedCategories(new Set());
  }, []);

  const handleClose = useCallback(() => {
    if (isConverting) return;
    resetWizard();
    onClose();
  }, [isConverting, resetWizard, onClose]);

  const featuresData = featuresQuery.data;
  const handleNext = useCallback(async () => {
    if (step === 1) {
      if (!selectedEdition) return;
      setStep(2);
      if (selectedEdition.isContactSalesOnly) {
        setS2((prev) => ({ ...prev, useCustomPrice: true }));
      }
    } else if (step === 2) {
      if (s2.useCustomPrice && !validateAmount(s2.negotiatedAmount)) return;
      setStep(3);
      if (featuresData) initOverrides(featuresData);
    } else if (step === 3) {
      setStep(4);
    }
  }, [step, selectedEdition, s2, validateAmount, featuresData, initOverrides]);

  const handleBack = useCallback(() => {
    if (step > 1) setStep((prev) => (prev - 1) as WizardStep);
  }, [step]);

  const handleSubmit = useCallback(async () => {
    const featureOverrides: FeatureOverride[] = Object.entries(overrides)
      .filter(([fid, val]) => {
        const feature = featureGroups.flatMap((g) => g.features).find((f) => f.featureId === fid);
        return feature && val !== feature.editionValue;
      })
      .map(([featureId, value]) => ({ featureId, value }));

    const negotiatedAmount =
      s2.useCustomPrice && s2.negotiatedAmount.trim() ? parseFloat(s2.negotiatedAmount) : undefined;

    await onConvert({
      editionId: selectedEdition?.id,
      tenantCode: s2.tenantCode.trim() || undefined,
      adminEmail: s2.adminEmail.trim() || undefined,
      subscriptionType: s2.subscriptionType || undefined,
      currency: s2.currency || undefined,
      conversionNote: s2.conversionNote.trim() || undefined,
      negotiatedAmount,
      negotiatedCurrency: s2.useCustomPrice ? s2.negotiatedCurrency : undefined,
      featureOverrides: featureOverrides.length > 0 ? featureOverrides : undefined,
    });
  }, [overrides, featureGroups, s2, selectedEdition, onConvert]);

  const handleOverrideChange = useCallback((featureId: string, value: string) => {
    setOverrides((p) => ({ ...p, [featureId]: value }));
  }, []);

  const handleAmountChange = useCallback(
    (val: string) => {
      setS2((p) => ({ ...p, negotiatedAmount: val }));
      if (amountError) validateAmount(val);
    },
    [amountError, validateAmount]
  );

  return {
    step,
    selectedEdition,
    setSelectedEdition: setSelectedEditionOverride,
    s2,
    setS2,
    amountError,
    overrides,
    expandedCategories,
    featureGroups,
    overrideCount,
    isLoadingEditions: editionsQuery.isLoading,
    editions: editionsQuery.data,
    isLoadingFeatures: featuresQuery.isLoading,
    handleClose,
    handleNext,
    handleBack,
    handleSubmit,
    toggleCategory,
    handleOverrideChange,
    handleAmountChange,
  };
}

import type {
  IOnboardingQuestionRepository,
  OnboardingQuestionsListParams,
} from "../../domain/interfaces/IOnboardingQuestionRepository";
import type { IOnboardingQuestionService } from "../../domain/interfaces/IOnboardingQuestionService";
import type {
  CreateOnboardingQuestionRequest,
  UpdateOnboardingQuestionRequest,
  AnswerOptionRequest,
} from "../../domain/entities/OnboardingQuestionRequests";
import { OnboardingQuestionMapper } from "../mappers/OnboardingQuestionMapper";
import type {
  OnboardingQuestion,
  AnswerOptionData,
} from "../../domain/entities/OnboardingQuestion";
import type { PagedResult } from "@core/interfaces/common.interface";

/**
 * Repository layer implementing client request queries for onboarding question.
 * Calls base API service routines and resolves DTO objects mapping to domain entities.
 */
export class OnboardingQuestionRepository implements IOnboardingQuestionRepository {
  constructor(private readonly service: IOnboardingQuestionService) {}

  async getAll(params: OnboardingQuestionsListParams): Promise<PagedResult<OnboardingQuestion>> {
    const result = await this.service.getAll(params);
    return {
      items: result.items.map((m) => OnboardingQuestionMapper.toEntity(m)),
      totalCount: result.totalCount,
      pageNumber: result.pageNumber,
      pageSize: result.pageSize,
      totalPages: result.totalPages,
      hasNextPage: result.pageNumber < result.totalPages,
      hasPreviousPage: result.pageNumber > 1,
    };
  }

  async getById(id: string): Promise<OnboardingQuestion> {
    const model = await this.service.getById(id);
    return OnboardingQuestionMapper.toEntity(model);
  }

  async create(request: CreateOnboardingQuestionRequest): Promise<string> {
    const result = await this.service.create(request);
    return result.id;
  }

  async update(id: string, request: UpdateOnboardingQuestionRequest): Promise<void> {
    await this.service.update(id, request);
  }

  async delete(id: string): Promise<void> {
    await this.service.delete(id);
  }

  async listOptions(questionId: string): Promise<AnswerOptionData[]> {
    try {
      const models = await this.service.listOptions(questionId);
      return models.map((m) => ({
        id: m.id,
        value: m.value,
        labelEn: m.labelEn,
        labelAr: m.labelAr,
        sublabelEn: m.sublabelEn,
        sublabelAr: m.sublabelAr,
        iconKey: m.iconKey,
        sortOrder: m.sortOrder,
        signalWeight: m.signalWeight,
        isActive: m.isActive,
      }));
    } catch (_error) {
      // Fallback to fetching the entire question if the options sub-resource endpoint is not yet active/recompiled
      const question = await this.getById(questionId);
      return question.options;
    }
  }

  async createOption(questionId: string, request: AnswerOptionRequest): Promise<string> {
    const result = await this.service.createOption(questionId, request);
    return result.id;
  }

  async updateOption(
    questionId: string,
    optionId: string,
    request: AnswerOptionRequest
  ): Promise<void> {
    await this.service.updateOption(questionId, optionId, request);
  }

  async deleteOption(questionId: string, optionId: string): Promise<void> {
    await this.service.deleteOption(questionId, optionId);
  }

  async reorderOptions(questionId: string, orderedIds: string[]): Promise<void> {
    await this.service.reorderOptions(questionId, orderedIds);
  }
}

/**
 * CommissionRateConfig
 * Dialog for setting or clearing a per-tenant commission rate override.
 * Shows the 3-level resolution hierarchy clearly.
 */
"use client";

import { useEffect, useMemo } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@core/ui/dialog";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Badge } from "@core/ui/badge";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
} from "@core/ui/form";
import { Info, X } from "lucide-react";
import type { ConnectAccountListItem } from "../../domain/entities/ConnectAccount";

type RateTarget = ConnectAccountListItem & { commissionRate?: number };

interface CommissionRateConfigProps {
  account: RateTarget | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (tenantId: string, rate: number | null) => void;
  isSaving: boolean;
  t: (key: string) => string;
}

interface RateFormValues {
  rate: string;
}

function buildSchema(t: (key: string) => string) {
  return z.object({
    rate: z.string().refine(
      (val) => {
        if (val === "") return true;
        const parsed = parseFloat(val);
        return !isNaN(parsed) && parsed >= 0 && parsed <= 50;
      },
      { message: t("entitlements.stripeConnect.commissionRateInvalid") }
    ),
  });
}

function toDefaultValues(account: RateTarget): RateFormValues {
  return { rate: account.commissionRate != null ? (account.commissionRate * 100).toFixed(2) : "" };
}

interface CommissionRateFormProps {
  account: RateTarget;
  onClose: () => void;
  onSave: (tenantId: string, rate: number | null) => void;
  isSaving: boolean;
  t: (key: string) => string;
}

/**
 * The dialog's body — a real react-hook-form instance so the field wears the
 * shared Form anatomy (label/control/hint/error on one rhythm, aria-invalid
 * driving the input's error skin) instead of hand-rolled state + a bare
 * validation string.
 */
function CommissionRateForm({ account, onClose, onSave, isSaving, t }: CommissionRateFormProps) {
  const schema = useMemo(() => buildSchema(t), [t]);
  const form = useForm<RateFormValues>({
    resolver: zodResolver(schema),
    defaultValues: toDefaultValues(account),
  });

  const tenantId = account.tenantId;
  const commissionRate = account.commissionRate;
  useEffect(() => {
    form.reset(toDefaultValues(account));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tenantId, commissionRate]);

  const onSubmit = (values: RateFormValues) => {
    if (values.rate === "") {
      onSave(account.tenantId, null);
      return;
    }
    onSave(account.tenantId, parseFloat(values.rate) / 100);
  };

  const handleClear = () => {
    form.setValue("rate", "", { shouldValidate: true });
    onSave(account.tenantId, null);
  };

  const effectiveRatePercent =
    account.effectiveCommissionRate != null
      ? (account.effectiveCommissionRate * 100).toFixed(2)
      : "—";

  const rateValue = form.watch("rate");

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4 py-2">
        {/* Effective rate display */}
        <div className="space-y-2 rounded-nx-md border border-nx-line bg-nx-raised p-3">
          <div className="flex items-center gap-2 text-sm font-medium text-nx-ink">
            <Info className="h-4 w-4 shrink-0 text-nx-ink-3" aria-hidden="true" />
            <span>
              {t("entitlements.stripeConnect.effectiveRate")}:{" "}
              <span className="tabular-nums">{effectiveRatePercent}%</span>
            </span>
          </div>
          <p className="text-xs leading-relaxed text-nx-ink-2">
            {t("entitlements.stripeConnect.effectiveRateDesc")}
          </p>
          {/* Resolution chain badges */}
          <div className="mt-1 flex flex-wrap gap-1">
            {(["tenantOverride", "editionRate", "globalDefault"] as const).map((level) => (
              <Badge key={level} variant="outline" className="font-normal">
                {t(`entitlements.stripeConnect.rateLevel.${level}`)}
              </Badge>
            ))}
          </div>
        </div>

        {/* Rate input */}
        <FormField
          control={form.control}
          name="rate"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("entitlements.stripeConnect.commissionRateOverride")} (%)</FormLabel>
              <div className="flex gap-2">
                <FormControl>
                  <Input
                    type="number"
                    min={0}
                    max={50}
                    step={0.01}
                    placeholder={t("entitlements.stripeConnect.commissionRatePlaceholder")}
                    {...field}
                  />
                </FormControl>
                {rateValue !== "" && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    onClick={() => form.setValue("rate", "", { shouldValidate: true })}
                    aria-label={t("common.clearSelection")}
                  >
                    <X className="h-4 w-4" aria-hidden="true" />
                  </Button>
                )}
              </div>
              <FormDescription>
                {t("entitlements.stripeConnect.commissionRateFieldHint")}
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <DialogFooter className="gap-2">
          {account.commissionRate != null && (
            <Button type="button" variant="outline" onClick={handleClear} disabled={isSaving}>
              {t("entitlements.stripeConnect.commissionRateClearAction")}
            </Button>
          )}
          <Button type="button" variant="ghost" onClick={onClose} disabled={isSaving}>
            {t("common.cancel")}
          </Button>
          <Button type="submit" loading={isSaving}>
            {t("common.save")}
          </Button>
        </DialogFooter>
      </form>
    </Form>
  );
}

/**
 * Presentation UI component rendering the commission rate config.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function CommissionRateConfig({
  account,
  isOpen,
  onClose,
  onSave,
  isSaving,
  t,
}: CommissionRateConfigProps) {
  if (!account) return null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[480px]">
        <DialogHeader>
          <DialogTitle>{t("entitlements.stripeConnect.commissionRateOverride")}</DialogTitle>
          <DialogDescription>
            {t("entitlements.stripeConnect.commissionRateDesc")}
          </DialogDescription>
        </DialogHeader>

        <CommissionRateForm
          key={account.tenantId}
          account={account}
          onClose={onClose}
          onSave={onSave}
          isSaving={isSaving}
          t={t}
        />
      </DialogContent>
    </Dialog>
  );
}

// FILE-EXCEPTION: file length
// UI-EXCEPTION: compact studio layout
"use client";

import { useState, useCallback } from "react";
import { useDocsI18n } from "../../providers/DocsI18nProvider";

interface CodeBlockProps {
  code: string;
  language: string;
  filename?: string;
  highlightLines?: number[];
}

/**
 * Minimal syntax tokenizer — covers keywords, strings, comments, types, functions.
 * No external dependency like Prism.js needed.
 */
function tokenize(code: string, language: string): { text: string; className: string }[][] {
  const lines = code.split("\n");

  // Language-specific keyword sets
  const csharpKeywords = new Set([
    "public",
    "private",
    "protected",
    "internal",
    "static",
    "class",
    "interface",
    "record",
    "struct",
    "enum",
    "namespace",
    "using",
    "var",
    "new",
    "return",
    "if",
    "else",
    "switch",
    "case",
    "break",
    "for",
    "foreach",
    "while",
    "do",
    "try",
    "catch",
    "finally",
    "throw",
    "async",
    "await",
    "void",
    "string",
    "int",
    "bool",
    "double",
    "float",
    "decimal",
    "long",
    "byte",
    "null",
    "true",
    "false",
    "readonly",
    "const",
    "override",
    "virtual",
    "abstract",
    "sealed",
    "partial",
    "this",
    "base",
    "typeof",
    "is",
    "as",
    "in",
    "out",
    "ref",
    "where",
    "get",
    "set",
    "value",
    "yield",
    "default",
    "object",
    "Task",
    "List",
    "Dictionary",
  ]);
  const tsKeywords = new Set([
    "import",
    "export",
    "from",
    "const",
    "let",
    "var",
    "function",
    "return",
    "if",
    "else",
    "for",
    "while",
    "do",
    "switch",
    "case",
    "break",
    "continue",
    "new",
    "this",
    "class",
    "extends",
    "implements",
    "interface",
    "type",
    "enum",
    "async",
    "await",
    "try",
    "catch",
    "finally",
    "throw",
    "typeof",
    "instanceof",
    "in",
    "of",
    "null",
    "undefined",
    "true",
    "false",
    "void",
    "never",
    "any",
    "string",
    "number",
    "boolean",
    "readonly",
    "abstract",
    "static",
    "public",
    "private",
    "protected",
    "default",
    "as",
    "is",
    "keyof",
    "infer",
    "satisfies",
  ]);
  const sqlKeywords = new Set([
    "SELECT",
    "FROM",
    "WHERE",
    "INSERT",
    "INTO",
    "VALUES",
    "UPDATE",
    "SET",
    "DELETE",
    "CREATE",
    "TABLE",
    "ALTER",
    "DROP",
    "INDEX",
    "JOIN",
    "LEFT",
    "RIGHT",
    "INNER",
    "OUTER",
    "ON",
    "AND",
    "OR",
    "NOT",
    "NULL",
    "PRIMARY",
    "KEY",
    "FOREIGN",
    "REFERENCES",
    "UNIQUE",
    "DEFAULT",
    "ORDER",
    "BY",
    "GROUP",
    "HAVING",
    "LIMIT",
    "OFFSET",
    "AS",
    "DISTINCT",
    "COUNT",
    "SUM",
    "AVG",
    "MAX",
    "MIN",
    "LIKE",
    "IN",
    "BETWEEN",
    "EXISTS",
    "CASE",
    "WHEN",
    "THEN",
    "ELSE",
    "END",
    "IS",
    "INT",
    "VARCHAR",
    "TEXT",
    "BOOLEAN",
    "DATETIME",
    "NVARCHAR",
    "BIT",
    "IDENTITY",
    "CONSTRAINT",
    "CASCADE",
    "GO",
    "EXEC",
    "DECLARE",
  ]);

  const lang = language.toLowerCase();
  let keywords: Set<string>;
  let commentStart: string;
  let multiCommentStart: string;
  let multiCommentEnd: string;

  if (lang === "csharp" || lang === "cs" || lang === "c#") {
    keywords = csharpKeywords;
    commentStart = "//";
    multiCommentStart = "/*";
    multiCommentEnd = "*/";
  } else if (lang === "sql") {
    keywords = sqlKeywords;
    commentStart = "--";
    multiCommentStart = "/*";
    multiCommentEnd = "*/";
  } else {
    keywords = tsKeywords;
    commentStart = "//";
    _multiCommentStart = "/*";
    _multiCommentEnd = "*/";
  }

  return lines.map((line) => {
    const tokens: { text: string; className: string }[] = [];
    let i = 0;

    while (i < line.length) {
      // Comments
      if (line.slice(i).startsWith(commentStart)) {
        tokens.push({ text: line.slice(i), className: "token-comment" });
        break;
      }

      // Strings (double quote)
      if (line[i] === '"' || line[i] === "'") {
        const quote = line[i];
        let end = i + 1;
        while (end < line.length && line[end] !== quote) {
          if (line[end] === "\\") end++;
          end++;
        }
        end = Math.min(end + 1, line.length);
        tokens.push({ text: line.slice(i, end), className: "token-string" });
        i = end;
        continue;
      }

      // Template literals
      if (line[i] === "`") {
        let end = i + 1;
        while (end < line.length && line[end] !== "`") {
          if (line[end] === "\\") end++;
          end++;
        }
        end = Math.min(end + 1, line.length);
        tokens.push({ text: line.slice(i, end), className: "token-string" });
        i = end;
        continue;
      }

      // Decorators / Attributes
      if (line[i] === "@" || (line[i] === "[" && /^[A-Z]/.test(line[i + 1] || ""))) {
        let end = i + 1;
        while (end < line.length && /[\w.]/.test(line[end])) end++;
        if (line[end] === "]") end++;
        tokens.push({ text: line.slice(i, end), className: "token-decorator" });
        i = end;
        continue;
      }

      // Numbers
      if (/[0-9]/.test(line[i]) && (i === 0 || !/[\w]/.test(line[i - 1]))) {
        let end = i;
        while (end < line.length && /[0-9.]/.test(line[end])) end++;
        tokens.push({ text: line.slice(i, end), className: "token-number" });
        i = end;
        continue;
      }

      // Words
      if (/[a-zA-Z_$]/.test(line[i])) {
        let end = i;
        while (end < line.length && /[\w$]/.test(line[end])) end++;
        const word = line.slice(i, end);

        if (keywords.has(word)) {
          tokens.push({ text: word, className: "token-keyword" });
        } else if (/^[A-Z]/.test(word) && word.length > 1) {
          tokens.push({ text: word, className: "token-type" });
        } else if (line[end] === "(") {
          tokens.push({ text: word, className: "token-function" });
        } else {
          tokens.push({ text: word, className: "" });
        }
        i = end;
        continue;
      }

      // Operators
      if (/[+\-*/%=<>!&|^~?:]/.test(line[i])) {
        let end = i + 1;
        while (end < line.length && /[+\-*/%=<>!&|^~?:]/.test(line[end])) end++;
        tokens.push({ text: line.slice(i, end), className: "token-operator" });
        i = end;
        continue;
      }

      // Punctuation
      if (/[{}()[\],;.]/.test(line[i])) {
        tokens.push({ text: line[i], className: "token-punctuation" });
        i++;
        continue;
      }

      // Whitespace and other chars
      tokens.push({ text: line[i], className: "" });
      i++;
    }

    return tokens;
  });
}

/**
 * Presentation UI component rendering the code block.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
const LANG_LABELS: Record<string, string> = {
  csharp: "C#",
  cs: "C#",
  "c#": "C#",
  typescript: "TypeScript",
  ts: "TypeScript",
  javascript: "JavaScript",
  js: "JavaScript",
  jsx: "JSX",
  tsx: "TSX",
  json: "JSON",
  http: "HTTP",
  sql: "SQL",
  bash: "Shell",
  shell: "Shell",
  sh: "Shell",
  yaml: "YAML",
  yml: "YAML",
  xml: "XML",
  html: "HTML",
  css: "CSS",
  text: "Text",
  plaintext: "Text",
};

export function CodeBlock({ code, language, filename, highlightLines }: CodeBlockProps) {
  const { t } = useDocsI18n();
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
    }
  }, [code]);

  const langLabel = LANG_LABELS[language?.toLowerCase() ?? ""] ?? language ?? "Code";
  const tokenizedLines = tokenize(code.trim(), language);
  const highlightSet = new Set(highlightLines || []);

  const sampleName = filename ? `${langLabel} — ${filename}` : langLabel;

  return (
    <div className="docs-code-block">
      <div className="docs-code-header">
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          {filename && <span className="docs-code-filename">{filename}</span>}
          <span className="docs-code-lang">{langLabel}</span>
        </div>
        <button
          type="button"
          className="docs-code-copy"
          data-copied={copied}
          onClick={handleCopy}
          aria-label={t("common.copyCodeSample", { sample: sampleName })}
        >
          {copied ? (
            <>
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                aria-hidden="true"
              >
                <polyline points="20 6 9 17 4 12" />
              </svg>
              {t("common.codeCopied")}
            </>
          ) : (
            <>
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                aria-hidden="true"
              >
                <rect width="14" height="14" x="8" y="8" rx="2" ry="2" />
                <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />
              </svg>
              {t("common.copyCode")}
            </>
          )}
        </button>
      </div>
      {/* A horizontally scrollable region must be reachable by keyboard, or a
          long line is simply unreadable without a mouse. */}
      <pre className="docs-code-pre" tabIndex={0} role="region" aria-label={sampleName}>
        <code>
          {tokenizedLines.map((lineTokens, lineIdx) => {
            const isHighlighted = highlightSet.has(lineIdx + 1);
            const lineContent = lineTokens.map((token, tokIdx) => (
              <span key={tokIdx} className={token.className || undefined}>
                {token.text}
              </span>
            ));

            return (
              <span
                key={lineIdx}
                className={isHighlighted ? "docs-code-line-highlight" : undefined}
              >
                {lineContent}
                {lineIdx < tokenizedLines.length - 1 ? "\n" : ""}
              </span>
            );
          })}
        </code>
      </pre>
    </div>
  );
}
